@Singleton
public class ExtendedFreezeTimersService
{
	private static final String CORE_TIMERS_GROUP = "timers";
	private static final String CORE_SHOW_FREEZES_KEY = "showFreezes";
	private static final int INACTIVITY_TIMEOUT_TICKS = 50;
	private static final int SWAMPBARK_TICKS_PER_RELEVANT_PIECE = 2;

	private static final Set<Integer> ANCIENT_SCEPTRES = buildAncientSceptres();
	private static final Set<Integer> SWAMPBARK_ITEMS = buildSwampbarkItems();
	private static final Map<Integer, FreezeType> GRAPHIC_TO_TYPE = buildGraphicMap();
	private static final Set<Integer> FORCED_MOVEMENT_SEEDS = buildForcedMovementSeeds();
	private static final int SPEAR_GRAPHIC_ID = SpotanimID.STUNNED_SHOVE;

	private final Client client;
	private final ConfigManager configManager;
	private final ChatMessageManager chatMessageManager;
	private final SpriteManager spriteManager;
	private final InfoBoxManager infoBoxManager;
	private final WildyQoLConfig config;

	private WildyQoLPlugin plugin;
	private Player currentOpponent;
	private String currentOpponentName;
	private int lastActivityTick = -1;
	private FreezeTimer activeTimer;
	private int freezeAppliedTick = -1;
	private int lastFrozenMessageTick = -1;
	private WorldPoint lastPoint;
	private int lastSeedCount = -1;
	private boolean pendingForcedMovement;
	private int forcedMovementTick = -1;
	private final Set<Integer> lastStandardSpotAnims = new HashSet<>();

	@Inject
	public ExtendedFreezeTimersService(
		Client client,
		ConfigManager configManager,
		ChatMessageManager chatMessageManager,
		SpriteManager spriteManager,
		InfoBoxManager infoBoxManager,
		WildyQoLConfig config)
	{
		this.client = client;
		this.configManager = configManager;
		this.chatMessageManager = chatMessageManager;
		this.spriteManager = spriteManager;
		this.infoBoxManager = infoBoxManager;
		this.config = config;
	}

	public void startUp(WildyQoLPlugin plugin)
	{
		this.plugin = plugin;
		lastSeedCount = -1;
		pendingForcedMovement = false;
		forcedMovementTick = -1;
		resetStandardSpotAnimTracking();
		if (!isEnabled())
		{
			return;
		}

		disableDuplicateTimersIfNeeded();
	}

	public void shutDown()
	{
		removeActiveTimer();
		removeFreezeTimerInfoBox();
		clearOpponent();
		resetStandardSpotAnimTracking();
		plugin = null;
		pendingForcedMovement = false;
		forcedMovementTick = -1;
		lastSeedCount = -1;
	}

	public void onConfigChanged(ConfigChanged event)
	{
		if (CORE_TIMERS_GROUP.equals(event.getGroup()) && CORE_SHOW_FREEZES_KEY.equals(event.getKey()))
		{
			disableDuplicateTimersIfNeeded();
			return;
		}

		if (!"wildyqol".equals(event.getGroup()))
		{
			return;
		}

		if ("warnDuplicateFreezeTimers".equals(event.getKey()))
		{
			disableDuplicateTimersIfNeeded();
			return;
		}

		if (!"enableExtendedFreezeTimersV2".equals(event.getKey()))
		{
			return;
		}

		if (config.enableExtendedFreezeTimers())
		{
			disableDuplicateTimersIfNeeded();
			lastSeedCount = -1;
			pendingForcedMovement = false;
			forcedMovementTick = -1;
			resetStandardSpotAnimTracking();
		}
		else
		{
			removeActiveTimer();
			clearOpponent();
			pendingForcedMovement = false;
			forcedMovementTick = -1;
			resetStandardSpotAnimTracking();
		}
	}

	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGING_IN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST || state == GameState.LOGIN_SCREEN)
		{
			removeActiveTimer();
			clearOpponent();
			pendingForcedMovement = false;
			forcedMovementTick = -1;
			lastSeedCount = -1;
			resetStandardSpotAnimTracking();
			return;
		}

		if (!isEnabled())
		{
			return;
		}

		if (state == GameState.LOGGED_IN)
		{
			lastSeedCount = -1;
		}
	}

	public void onInteractingChanged(InteractingChanged event)
	{
		if (!isEnabled())
		{
			return;
		}

		if (!(event.getSource() instanceof Player) || !(event.getTarget() instanceof Player))
		{
			return;
		}

		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		Player candidate = null;
		if (event.getSource() == local)
		{
			candidate = (Player) event.getTarget();
		}
		else if (event.getTarget() == local)
		{
			candidate = (Player) event.getSource();
		}

		if (candidate == null)
		{
			return;
		}

		if (currentOpponent != null && Objects.equals(currentOpponentName, candidate.getName()))
		{
			refreshActivity();
			return;
		}

		setOpponent(candidate);
	}

	public void onAnimationChanged(AnimationChanged event)
	{
		if (!isEnabled())
		{
			return;
		}

		Actor actor = event.getActor();
		if (actor == null)
		{
			return;
		}

		if (actor == client.getLocalPlayer() || isOpponent(actor))
		{
			refreshActivity();
		}
	}

	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (!isEnabled())
		{
			return;
		}

		Actor actor = event.getActor();
		if (actor == null)
		{
			return;
		}

		if (actor == client.getLocalPlayer() || isOpponent(actor))
		{
			refreshActivity();
		}
	}

	public void onPlayerDespawned(PlayerDespawned event)
	{
		if (!isEnabled())
		{
			return;
		}

		if (isOpponent(event.getPlayer()))
		{
			clearOpponent();
		}
	}

	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}

		ItemContainer container = event.getItemContainer();
		int currentSeedCount = countSeeds(container);
		if (lastSeedCount < 0)
		{
			lastSeedCount = currentSeedCount;
			return;
		}

		int previousSeedCount = lastSeedCount;
		lastSeedCount = currentSeedCount;

		if (!isForcedMovementProtectionEnabled())
		{
			return;
		}

		if (isFreezeTimerActive() && previousSeedCount >= 0 && currentSeedCount < previousSeedCount)
		{
			registerForcedMovement();
		}
	}

	public void onGraphicChanged(GraphicChanged event)
	{
		if (!isEnabled())
		{
			return;
		}

		Actor actor = event.getActor();
		Player local = client.getLocalPlayer();
		if (actor != local || local == null)
		{
			return;
		}

		int graphicId = actor.getGraphic();

		if (isForcedMovementProtectionEnabled() && isFreezeTimerActive() && actor.hasSpotAnim(SPEAR_GRAPHIC_ID))
		{
			registerForcedMovement();
		}

		// Detect standard freezes immediately, while retaining the game-tick scan as a fallback.
		checkStandardFreezeSpotAnims(local);

		FreezeType type = GRAPHIC_TO_TYPE.get(graphicId);
		if (type == null)
		{
			return;
		}

		int tickCount = client.getTickCount();

		if (!type.isAncient())
		{
			// The spot animation list may not have updated yet when GraphicChanged is posted.
			if (!lastStandardSpotAnims.contains(graphicId))
			{
				refreshActivity();
				startTimer(type);
				lastStandardSpotAnims.add(graphicId);
			}
			return;
		}

		// For ancient freezes, only allow processing on the same tick as the freeze chat message.
		if (type.isAncient() && lastFrozenMessageTick != tickCount)
		{
			return;
		}

		refreshActivity();

		// Replace with shorter freeze if a downgrade is detected on the same tick.
		if (isFreezeTimerActive() && freezeAppliedTick == tickCount && type.getBaseTicks() < activeTimer.getFreezeType().getBaseTicks())
		{
			startTimer(type);
			return;
		}

		// Reapply if we got frozen again.
		if (!isFreezeTimerActive() || type.getBaseTicks() >= activeTimer.getFreezeType().getBaseTicks() || freezeAppliedTick != tickCount)
		{
			startTimer(type);
		}
	}

	public void onGameTick(GameTick event)
	{
		if (!isEnabled())
		{
			return;
		}

		Player local = client.getLocalPlayer();
		if (local == null)
		{
			removeActiveTimer();
			clearOpponent();
			resetStandardSpotAnimTracking();
			return;
		}

		int tickCount = client.getTickCount();
		checkStandardFreezeSpotAnims(local);
		if (isForcedMovementProtectionEnabled() && isFreezeTimerActive() && local.hasSpotAnim(SPEAR_GRAPHIC_ID))
		{
			registerForcedMovement();
		}

		if (isFreezeTimerActive() && freezeAppliedTick != tickCount)
		{
			WorldPoint current = local.getWorldLocation();
			if (current != null && lastPoint != null && !current.equals(lastPoint))
			{
				if (!shouldIgnoreMovementClear(tickCount))
				{
					removeActiveTimer();
				}
			}
		}

		if (currentOpponent != null && lastActivityTick > -1 && tickCount - lastActivityTick > INACTIVITY_TIMEOUT_TICKS)
		{
			clearOpponent();
		}

		lastPoint = local.getWorldLocation();
	}

	public void onChatMessage(ChatMessage event)
	{
		if (!isEnabled())
		{
			return;
		}

		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		if ("You have been frozen!".equals(message))
		{
			lastFrozenMessageTick = client.getTickCount();
			startTimer(FreezeType.ICE_BARRAGE);
		}
	}

	private void startTimer(FreezeType type)
	{
		removeActiveTimer();

		Duration duration = calculateDuration(type);
		activeTimer = new FreezeTimer(type, duration, plugin);
		infoBoxManager.addInfoBox(activeTimer);
		activeTimer.setActive(true);
		spriteManager.getSpriteAsync(type.getSpriteId(), 0, activeTimer);
		activeTimer.setTooltip(type.getDisplayName());
		freezeAppliedTick = client.getTickCount();

		// Recheck in case the core timer was enabled without a config event reaching this plugin.
		disableDuplicateTimersIfNeeded();
	}

	private Duration calculateDuration(FreezeType type)
	{
		long ticks = type.getBaseTicks();
		if (type.isAncient())
		{
			if (opponentHasAncientSceptre())
			{
				ticks = Math.round(ticks * 1.1d);
			}
		}
		else
		{
			ticks = calculateSwampbarkAdjustedTicks(ticks, countSwampbarkPieces());
		}

		ticks = Math.max(1L, ticks);
		return Duration.of(ticks, RSTimeUnit.GAME_TICKS);
	}

	static long calculateSwampbarkAdjustedTicks(long baseTicks, int pieceCount)
	{
		return baseTicks + (long) Math.max(0, pieceCount) * SWAMPBARK_TICKS_PER_RELEVANT_PIECE;
	}

	private void removeActiveTimer()
	{
		if (activeTimer != null)
		{
			activeTimer.setActive(false);
			infoBoxManager.removeInfoBox(activeTimer);
			activeTimer = null;
		}

		freezeAppliedTick = -1;
		pendingForcedMovement = false;
		forcedMovementTick = -1;
	}

	private boolean isFreezeTimerActive()
	{
		return activeTimer != null && activeTimer.isActive();
	}

	private void removeFreezeTimerInfoBox()
	{
		if (activeTimer == null)
		{
			return;
		}

		infoBoxManager.removeInfoBox(activeTimer);
		activeTimer = null;
	}

	private void setOpponent(Player opponent)
	{
		currentOpponent = opponent;
		currentOpponentName = opponent != null ? opponent.getName() : null;
		refreshActivity();
	}

	private void clearOpponent()
	{
		currentOpponent = null;
		currentOpponentName = null;
		lastActivityTick = -1;
	}

	private boolean isOpponent(Actor actor)
	{
		return actor instanceof Player && currentOpponent != null && currentOpponent == actor;
	}

	private void refreshActivity()
	{
		lastActivityTick = client.getTickCount();
	}

	private void checkStandardFreezeSpotAnims(Player local)
	{
		Set<Integer> current = new HashSet<>();
		FreezeType newType = null;

		for (FreezeType type : FreezeType.values())
		{
			if (type.isAncient())
			{
				continue;
			}

			int graphicId = type.getGraphicId();
			if (!local.hasSpotAnim(graphicId))
			{
				continue;
			}

			current.add(graphicId);
			if (!lastStandardSpotAnims.contains(graphicId))
			{
				if (newType == null || type.getBaseTicks() > newType.getBaseTicks())
				{
					newType = type;
				}
			}
		}

		if (newType != null)
		{
			refreshActivity();
			startTimer(newType);
		}

		lastStandardSpotAnims.clear();
		lastStandardSpotAnims.addAll(current);
	}

	private void resetStandardSpotAnimTracking()
	{
		lastStandardSpotAnims.clear();
	}

	private boolean shouldIgnoreMovementClear(int tickCount)
	{
		if (!isForcedMovementProtectionEnabled() || !pendingForcedMovement)
		{
			return false;
		}

		if (forcedMovementTick != -1 && tickCount - forcedMovementTick > 1)
		{
			pendingForcedMovement = false;
			forcedMovementTick = -1;
			return false;
		}

		pendingForcedMovement = false;
		forcedMovementTick = -1;
		return true;
	}

	private void registerForcedMovement()
	{
		pendingForcedMovement = true;
		forcedMovementTick = client.getTickCount();
	}

	private int countSeeds(ItemContainer container)
	{
		if (container == null)
		{
			return 0;
		}

		int count = 0;
		Item[] items = container.getItems();
		if (items == null)
		{
			return 0;
		}

		for (Item item : items)
		{
			if (item == null)
			{
				continue;
			}

			int itemId = item.getId();
			if (itemId <= 0)
			{
				continue;
			}

			if (FORCED_MOVEMENT_SEEDS.contains(itemId))
			{
				count += item.getQuantity();
			}
		}

		return count;
	}

	private boolean opponentHasAncientSceptre()
	{
		Player opponent = currentOpponent;
		if (opponent == null)
		{
			return false;
		}

		for (int itemId : getEquipmentIds(opponent))
		{
			if (ANCIENT_SCEPTRES.contains(itemId))
			{
				return true;
			}
		}

		return false;
	}

	private int countSwampbarkPieces()
	{
		Player opponent = currentOpponent;
		if (opponent == null)
		{
			return 0;
		}

		int count = 0;
		for (int itemId : getEquipmentIds(opponent))
		{
			if (SWAMPBARK_ITEMS.contains(itemId))
			{
				count++;
			}
		}

		return count;
	}

	private int[] getEquipmentIds(Player player)
	{
		PlayerComposition comp = player.getPlayerComposition();
		if (comp == null || comp.getEquipmentIds() == null)
		{
			return new int[0];
		}

		int[] equipmentIds = comp.getEquipmentIds();
		int[] fixed = new int[equipmentIds.length];
		for (int i = 0; i < equipmentIds.length; i++)
		{
			int id = equipmentIds[i];
			fixed[i] = id > PlayerComposition.ITEM_OFFSET ? id - PlayerComposition.ITEM_OFFSET : id;
		}

		return fixed;
	}

	private boolean isForcedMovementProtectionEnabled()
	{
		return isEnabled() && config.preserveFreezeTimerOnForcedMovement();
	}

	private boolean isEnabled()
	{
		return plugin != null && config.enableExtendedFreezeTimers();
	}

	private void disableDuplicateTimersIfNeeded()
	{
		if (!isEnabled() || !config.disableDuplicateFreezeTimers())
		{
			return;
		}

		Boolean coreFreeze = configManager.getConfiguration(CORE_TIMERS_GROUP, CORE_SHOW_FREEZES_KEY, Boolean.class);
		if (coreFreeze != null && !coreFreeze)
		{
			return;
		}

		configManager.setConfiguration(CORE_TIMERS_GROUP, CORE_SHOW_FREEZES_KEY, false);

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage("<col=ff9040>Wildy QoL:</col> Turned off \"Freeze timer\" in Timers & Buffs because extended freeze timers are enabled.")
			.build());
	}

	private static Set<Integer> buildAncientSceptres()
	{
		Set<Integer> ids = new HashSet<>();
		addVariations(ids, ItemID.ANCIENT_SCEPTRE);
		addVariations(ids, ItemID.ANCIENT_SCEPTRE_BLOOD);
		addVariations(ids, ItemID.ANCIENT_SCEPTRE_ICE);
		addVariations(ids, ItemID.ANCIENT_SCEPTRE_SMOKE);
		addVariations(ids, ItemID.ANCIENT_SCEPTRE_SHADOW);
		addVariations(ids, ItemID.ANCIENT_SCEPTRE_TROUVER);
		addVariations(ids, ItemID.ANCIENT_SCEPTRE_BLOOD_TROUVER);
		addVariations(ids, ItemID.ANCIENT_SCEPTRE_ICE_TROUVER);
		addVariations(ids, ItemID.ANCIENT_SCEPTRE_SMOKE_TROUVER);
		addVariations(ids, ItemID.ANCIENT_SCEPTRE_SHADOW_TROUVER);
		addVariations(ids, ItemID.ZURIELS_STAFF);
		addVariations(ids, ItemID.BR_ZURIELS_STAFF);
		addVariations(ids, ItemID.ZURIELS_STAFF_BH);
		addVariations(ids, ItemID.ZURIELS_STAFF_BH_INACTIVE);
		return ids;
	}

	private static Set<Integer> buildSwampbarkItems()
	{
		Set<Integer> ids = new HashSet<>();
		addVariations(ids, ItemID.SWAMPBARK_HELM);
		addVariations(ids, ItemID.SWAMPBARK_BODY);
		addVariations(ids, ItemID.SWAMPBARK_LEGS);
		return ImmutableSet.copyOf(ids);
	}

	private static Set<Integer> buildForcedMovementSeeds()
	{
		Set<Integer> seeds = new HashSet<>();
		addVariations(seeds, ItemID.MITHRIL_SEED);
		addVariations(seeds, ItemID.ADAMANT_SEED);
		return seeds;
	}

	private static Map<Integer, FreezeType> buildGraphicMap()
	{
		Map<Integer, FreezeType> map = new HashMap<>();
		for (FreezeType type : FreezeType.values())
		{
			map.put(type.getGraphicId(), type);
		}
		return map;
	}

	private static void addVariations(Set<Integer> ids, int itemId)
	{
		ids.add(itemId);
		ids.addAll(ItemVariationMapping.getVariations(itemId));
	}

	private enum FreezeType
	{
		BIND("Bind", SpriteID.Magicon2.BIND, SpotanimID.BIND_IMPACT, 8, false),
		SNARE("Snare", SpriteID.Magicon2.SNARE, SpotanimID.SNARE_IMPACT, 16, false),
		ENTANGLE("Entangle", SpriteID.Magicon2.ENTANGLE, SpotanimID.ENTANGLE_IMPACT, 24, false),
		ICE_RUSH("Ice rush", SpriteID.Magicon2.ICE_RUSH, SpotanimID.ICE_RUSH_IMPACT, 8, true),
		ICE_BURST("Ice burst", SpriteID.Magicon2.ICE_BURST, SpotanimID.ICE_BLITZ_IMPACT, 16, true),
		ICE_BLITZ("Ice blitz", SpriteID.Magicon2.ICE_BLITZ, SpotanimID.ICE_BURST_IMPACT, 24, true),
		ICE_BARRAGE("Ice barrage", SpriteID.Magicon2.ICE_BARRAGE, SpotanimID.ICE_BARRAGE_IMPACT, 32, true);

		private final String displayName;
		private final int spriteId;
		private final int graphicId;
		private final int baseTicks;
		private final boolean ancient;

		FreezeType(String displayName, int spriteId, int graphicId, int baseTicks, boolean ancient)
		{
			this.displayName = displayName;
			this.spriteId = spriteId;
			this.graphicId = graphicId;
			this.baseTicks = baseTicks;
			this.ancient = ancient;
		}

		int getSpriteId()
		{
			return spriteId;
		}

		int getGraphicId()
		{
			return graphicId;
		}

		int getBaseTicks()
		{
			return baseTicks;
		}

		boolean isAncient()
		{
			return ancient;
		}

		String getDisplayName()
		{
			return displayName;
		}
	}

	private class FreezeTimer extends Timer
	{
		private FreezeType freezeType;
		private boolean active;

		FreezeTimer(FreezeType freezeType, Duration duration, WildyQoLPlugin plugin)
		{
			super(duration.toMillis(), ChronoUnit.MILLIS, null, plugin);
			this.freezeType = freezeType;
			setPriority(InfoBoxPriority.MED);
		}

		void setFreezeType(FreezeType freezeType)
		{
			this.freezeType = freezeType;
		}

		void setActive(boolean active)
		{
			this.active = active;
		}

		boolean isActive()
		{
			return active && super.render();
		}

		FreezeType getFreezeType()
		{
			return freezeType;
		}

		@Override
		public boolean render()
		{
			return isEnabled()
				&& active
				&& client.getGameState() == GameState.LOGGED_IN
				&& super.render();
		}

		@Override
		public boolean cull()
		{
			return false;
		}

		@Override
		public String getName()
		{
			return freezeType.getDisplayName();
		}
	}
}

package com.wildyqol.itemskeptondeath;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.client.util.Text;
import com.wildyqol.WildyQoLConfig;

@Singleton
public class IkodParchmentRiskOverlay extends Overlay
{
    private static final int BASELINE_MARGIN = 4;
    private static final int LINE_SPACING = 4;

    private final Client client;
    private final WildyQoLConfig config;

    private boolean ikodOpen;
    private long surcharge;
    private long baseRisk;
    private Color labelColor = Color.WHITE;

    @Inject
    private IkodParchmentRiskOverlay(Client client, WildyQoLConfig config)
    {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    public void update(boolean ikodOpen, long surcharge, long baseRisk, Color labelColor)
    {
        this.ikodOpen = ikodOpen;
        this.surcharge = surcharge;
        this.baseRisk = baseRisk;
        this.labelColor = labelColor != null ? labelColor : Color.WHITE;
    }

    public void reset()
    {
        update(false, 0L, 0L, Color.WHITE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showIkodRepairCostsOverlay() || !ikodOpen)
        {
            return null;
        }

        Widget riskWidget = client.getWidget(InterfaceID.Deathkeep.VALUE);
        if (riskWidget == null || riskWidget.isHidden())
        {
            return null;
        }

        Rectangle bounds = riskWidget.getBounds();
        Widget messageWidget = client.getWidget(InterfaceID.Deathkeep.TOPAREA);
        Rectangle messageBounds = messageWidget != null ? messageWidget.getBounds() : null;
        boolean condensed = hasAdditionalMessage(messageWidget);

        if (bounds == null)
        {
            return null;
        }

        Font font = FontManager.getRunescapeSmallFont();
        graphics.setFont(font);

        String surchargeText = QuantityFormatter.formatNumber(surcharge);
        long totalRisk = baseRisk + surcharge;
        String totalRiskText = QuantityFormatter.formatNumber(totalRisk);

        String[] lines = condensed
            ? new String[] { "Total risk:", totalRiskText }
            : new String[] { "Repair costs:", surchargeText, "Total risk:", totalRiskText };

        Color[] colors = condensed
            ? new Color[] { labelColor, Color.WHITE }
            : new Color[] { labelColor, Color.WHITE, labelColor, Color.WHITE };

        int centerX = bounds.x + bounds.width / 2;
        int lineHeight = graphics.getFontMetrics().getHeight();
        int spacing = condensed ? 1 : LINE_SPACING;
        int step = lineHeight + spacing;
        int bottomY = bounds.y - BASELINE_MARGIN;

        if (condensed && messageBounds != null)
        {
            int requiredBottom = messageBounds.y + messageBounds.height + BASELINE_MARGIN + (lines.length - 1) * step;
            bottomY = Math.max(bottomY, requiredBottom);
            bottomY += 4;
        }

        int y = bottomY;

        for (int i = lines.length - 1; i >= 0; i--)
        {
            String line = lines[i];
            int textWidth = graphics.getFontMetrics().stringWidth(line);
            int textX = centerX - textWidth / 2;
            int textY = y;
            if (condensed)
            {
                if (i == 0)
                {
                    textY += 5;
                }
                else
                {
                    textY += 2;
                }
            }
            Point location = new Point(textX, textY);
            OverlayUtil.renderTextLocation(graphics, location, lines[i], colors[i]);
            y -= step;
        }

        return null;
    }

    private boolean hasAdditionalMessage(Widget messageWidget)
    {
        if (messageWidget == null)
        {
            return false;
        }

        StringBuilder textBuilder = new StringBuilder();
        appendWidgetText(textBuilder, messageWidget);

        Widget[] dynamicChildren = messageWidget.getDynamicChildren();
        if (dynamicChildren != null)
        {
            for (Widget child : dynamicChildren)
            {
                appendWidgetText(textBuilder, child);
            }
        }

        if (textBuilder.length() == 0)
        {
            return false;
        }

        String sanitized = Text.removeTags(textBuilder.toString()).toLowerCase();
        return sanitized.contains("player-owned house")
            || sanitized.contains("gravestone")
            || sanitized.contains("safe area");
    }

    private void appendWidgetText(StringBuilder builder, Widget widget)
    {
        if (widget == null)
        {
            return;
        }

        String text = widget.getText();
        if (text == null || text.isEmpty())
        {
            return;
        }

        if (builder.length() > 0)
        {
            builder.append('\n');
        }

        builder.append(text);
    }
}

package com.wildyqol.itemskeptondeath;

import com.wildyqol.WildyQoLConfig;
import java.awt.Color;
import java.util.ArrayDeque;
import java.util.Collections;
import java.util.Deque;
import java.util.IdentityHashMap;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Singleton
public class IkodParchmentRiskService
{
	private static final Pattern WILDERNESS_LEVEL_PATTERN = Pattern.compile("level\\s*:?\\s*(\\d+)", Pattern.CASE_INSENSITIVE);
	static final int DEATHKEEP_TOGGLE_UNCHECKED_SPRITE_ID = 8379;
	static final int DEATHKEEP_TOGGLE_CHECKED_SPRITE_ID = 8380;

	private final Client client;
	private final ItemManager itemManager;
	private final OverlayManager overlayManager;
	private final IkodParchmentRiskOverlay overlay;
	private final WildyQoLConfig config;

	@Inject
	private IkodParchmentRiskService(
		Client client,
		ItemManager itemManager,
		OverlayManager overlayManager,
		IkodParchmentRiskOverlay overlay,
		WildyQoLConfig config)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.overlayManager = overlayManager;
		this.overlay = overlay;
		this.config = config;
	}

	public void startUp()
	{
		overlayManager.add(overlay);
	}

	public void refresh()
	{
		updateUntradeablesRepairCost();
	}

	public void shutDown()
	{
		overlayManager.remove(overlay);
		overlay.reset();
	}

	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.DEATHKEEP)
		{
			updateUntradeablesRepairCost();
		}
	}

	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.DEATHKEEP)
		{
			overlay.reset();
		}
	}

	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (isIkodOpen())
		{
			updateUntradeablesRepairCost();
		}
	}

	public void onVarbitChanged(VarbitChanged event)
	{
		if (isIkodOpen())
		{
			updateUntradeablesRepairCost();
		}
	}

	public void onGameTick(GameTick event)
	{
		if (isIkodOpen())
		{
			updateUntradeablesRepairCost();
		}
	}

	private void updateUntradeablesRepairCost()
	{
		if (!config.showIkodRepairCostsOverlay())
		{
			overlay.reset();
			return;
		}

		if (!isIkodOpen())
		{
			overlay.reset();
			return;
		}

		Widget riskWidget = client.getWidget(InterfaceID.Deathkeep.VALUE);
		if (riskWidget == null || riskWidget.isHidden())
		{
			overlay.reset();
			return;
		}

		boolean aboveLevel20 = isAboveLevel20Selected();
		long surcharge = getUntradeablesRepairCost(aboveLevel20);
		long baseRisk = getGuideRiskValue(riskWidget);
		Color labelColor = deriveLabelColor(riskWidget);

		overlay.update(true, surcharge, baseRisk, labelColor);
	}

	private boolean isIkodOpen()
	{
		Widget root = client.getWidget(InterfaceID.Deathkeep.CONTENTS);
		return root != null && !root.isHidden();
	}

	private long getUntradeablesRepairCost(boolean aboveLevel20)
	{
		Set<Widget> visited = Collections.newSetFromMap(new IdentityHashMap<>());
		Deque<Widget> stack = new ArrayDeque<>();
		pushRoot(stack, client.getWidget(InterfaceID.Deathkeep.KEPT));
		pushRoot(stack, client.getWidget(InterfaceID.Deathkeep.GRAVE));

		if (stack.isEmpty())
		{
			pushRoot(stack, client.getWidget(InterfaceID.Deathkeep.ITEMS));
		}

		long repairCost = 0L;

		while (!stack.isEmpty())
		{
			Widget widget = stack.pop();
			if (widget == null || !visited.add(widget) || widget.isHidden())
			{
				continue;
			}

			repairCost += getRepairCostForWidget(widget, aboveLevel20);
			pushChildren(stack, widget.getDynamicChildren());
			pushChildren(stack, widget.getStaticChildren());
			pushChildren(stack, widget.getNestedChildren());
			pushChildren(stack, widget.getChildren());
		}

		return repairCost;
	}

	private void pushRoot(Deque<Widget> stack, Widget widget)
	{
		if (widget != null && !widget.isHidden())
		{
			stack.push(widget);
		}
	}

	private long getRepairCostForWidget(Widget widget, boolean aboveLevel20)
	{
		int itemId = widget.getItemId();
		if (itemId <= 0)
		{
			return 0L;
		}

		ItemComposition rawComposition = itemManager.getItemComposition(itemId);
		String rawItemName = rawComposition == null ? "" : rawComposition.getName();
		int canonicalId = itemManager.canonicalize(itemId);
		ItemComposition canonicalComposition = itemManager.getItemComposition(canonicalId);
		String canonicalItemName = canonicalComposition == null ? "" : canonicalComposition.getName();
		if (!isRepairCostCandidate(widget.getBorderType(), itemId, rawItemName, canonicalId, canonicalItemName))
		{
			return 0L;
		}

		long repairCost = getRepairCost(itemId, rawItemName, aboveLevel20);
		if (repairCost == 0L && canonicalId != itemId)
		{
			repairCost = getRepairCost(canonicalId, canonicalItemName, aboveLevel20);
		}

		return Math.max(1, widget.getItemQuantity()) * repairCost;
	}

	static boolean isRepairCostCandidate(int borderType, int itemId, String itemName, int canonicalId, String canonicalItemName)
	{
		boolean hasKnownRepairCost = IkodUntradeableRepairCosts.hasRepairCost(itemId, itemName)
			|| IkodUntradeableRepairCosts.hasRepairCost(canonicalId, canonicalItemName);
		return (borderType == 2 && hasKnownRepairCost)
			|| IkodUntradeableRepairCosts.isDisplayedBrokenOrMangled(itemName)
			|| IkodUntradeableRepairCosts.isDisplayedBrokenOrMangled(canonicalItemName);
	}

	private long getRepairCost(int itemId, String itemName, boolean aboveLevel20)
	{
		return IkodUntradeableRepairCosts.getRepairCost(
			itemId,
			itemName,
			aboveLevel20,
			itemManager::getItemPrice);
	}

	private void pushChildren(Deque<Widget> stack, Widget[] children)
	{
		if (children == null)
		{
			return;
		}

		for (Widget child : children)
		{
			if (child != null)
			{
				stack.push(child);
			}
		}
	}

	private boolean isAboveLevel20Selected()
	{
		Boolean checkboxState = getCheckboxState(client.getWidget(InterfaceID.Deathkeep.BUTTON3));
		if (checkboxState != null)
		{
			return checkboxState;
		}

		Widget wildernessLevelWidget = client.getWidget(InterfaceID.PvpIcons.WILDERNESSLEVEL);
		if (wildernessLevelWidget == null || wildernessLevelWidget.isHidden())
		{
			return false;
		}

		return isAboveLevel20(Text.removeTags(wildernessLevelWidget.getText()));
	}

	private Boolean getCheckboxState(Widget root)
	{
		if (root == null || root.isHidden())
		{
			return null;
		}

		Set<Widget> visited = Collections.newSetFromMap(new IdentityHashMap<>());
		Deque<Widget> stack = new ArrayDeque<>();
		boolean foundUncheckedSprite = false;
		stack.push(root);

		while (!stack.isEmpty())
		{
			Widget widget = stack.pop();
			if (widget == null || !visited.add(widget) || widget.isHidden())
			{
				continue;
			}

			Boolean state = parseDeathkeepToggleSprite(widget.getSpriteId());
			if (Boolean.TRUE.equals(state))
			{
				return true;
			}
			if (Boolean.FALSE.equals(state))
			{
				foundUncheckedSprite = true;
			}

			pushChildren(stack, widget.getDynamicChildren());
			pushChildren(stack, widget.getStaticChildren());
			pushChildren(stack, widget.getNestedChildren());
			pushChildren(stack, widget.getChildren());
		}

		return foundUncheckedSprite ? Boolean.FALSE : null;
	}

	static Boolean parseDeathkeepToggleSprite(int spriteId)
	{
		switch (spriteId)
		{
			case DEATHKEEP_TOGGLE_CHECKED_SPRITE_ID:
				return true;
			case DEATHKEEP_TOGGLE_UNCHECKED_SPRITE_ID:
				return false;
			default:
				return null;
		}
	}

	static boolean isAboveLevel20(String wildernessText)
	{
		Matcher matcher = WILDERNESS_LEVEL_PATTERN.matcher(wildernessText == null ? "" : wildernessText);
		return matcher.find() && Integer.parseInt(matcher.group(1)) > 20;
	}

	private long getGuideRiskValue(Widget riskWidget)
	{
		String rawText = riskWidget.getText();
		if (rawText == null)
		{
			return 0L;
		}

		String sanitized = Text.removeTags(rawText).replaceAll("[^0-9]", "");
		if (sanitized.isEmpty())
		{
			return 0L;
		}

		try
		{
			return Long.parseLong(sanitized);
		}
		catch (NumberFormatException ex)
		{
			return 0L;
		}
	}

	private Color deriveLabelColor(Widget riskWidget)
	{
		int color = riskWidget.getTextColor();
		if (color == 0)
		{
			return Color.WHITE;
		}

		return new Color(color | 0xFF000000, true);
	}
}

package com.wildyqol.misclick;

import com.wildyqol.AreaDetection;
import com.wildyqol.WildyQoLConfig;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.Point;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

@Singleton
public class FishInventoryIconOverlay extends WidgetItemOverlay
{
    private static final Color INVENTORY_BACKGROUND_RESIZABLE = new Color(62, 53, 41);
    private static final Color INVENTORY_BACKGROUND_FIXED = new Color(66, 58, 45);
    private static final float ACTIVE_ALPHA = 0.55f;
    private static final int ACTIVE_LINGER_CYCLES = 10;

    private final Client client;
    private final ItemManager itemManager;
    private final WildyQoLConfig config;
    private final Map<Long, ActiveState> recentActiveStates = new HashMap<>();
    private boolean wasDragging;

    @Inject
    private FishInventoryIconOverlay(Client client, ItemManager itemManager, WildyQoLConfig config)
    {
        this.client = client;
        this.itemManager = itemManager;
        this.config = config;
        drawAfterInterface(InterfaceID.INVENTORY);
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
    {
        if (!isInPvpArea())
        {
            return;
        }

        int replacementId = getReplacementId(itemId);
        if (replacementId == -1)
        {
            return;
        }

        Widget widget = widgetItem.getWidget();
        if (widget == null || widget.getParentId() != InterfaceID.Inventory.ITEMS)
        {
            return;
        }

        Rectangle bounds = widgetItem.getCanvasBounds();
        if (bounds == null)
        {
            return;
        }

        BufferedImage replacementImage = itemManager.getImage(replacementId, widgetItem.getQuantity(), false);
        if (replacementImage == null)
        {
            return;
        }

        BufferedImage originalImage = itemManager.getImage(itemId, widgetItem.getQuantity(), false);
        if (originalImage != null)
        {
            int clearX = bounds.x + (bounds.width - originalImage.getWidth()) / 2;
            int clearY = bounds.y + (bounds.height - originalImage.getHeight()) / 2;
            BufferedImage mask = maskWithBackground(originalImage, getInventoryBackgroundColor());
            graphics.drawImage(mask, clearX, clearY, null);
        }

        int drawX = bounds.x + (bounds.width - replacementImage.getWidth()) / 2;
        int drawY = bounds.y + (bounds.height - replacementImage.getHeight()) / 2;
        Graphics2D imageGraphics = (Graphics2D) graphics.create();
        if (isActiveWidget(widgetItem, bounds))
        {
            imageGraphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, ACTIVE_ALPHA));
        }
        imageGraphics.drawImage(replacementImage, drawX, drawY, null);
        imageGraphics.dispose();
    }

    private int getReplacementId(int itemId)
    {
        if (itemId == ItemID.MARLIN && config.marlinEqualsAnglerfish())
        {
            return ItemID.ANGLERFISH;
        }

        if (itemId == ItemID.HALIBUT && config.halibutEqualsKarambwan())
        {
            return ItemID.TBWT_COOKED_KARAMBWAN;
        }

        return -1;
    }

    private boolean isInPvpArea()
    {
        return AreaDetection.isRawPvpArea(client);
    }

    private BufferedImage maskWithBackground(BufferedImage source, Color background)
    {
        int width = source.getWidth();
        int height = source.getHeight();
        BufferedImage masked = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        int backgroundRgb = background.getRGB() & 0x00FFFFFF;

        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                int argb = source.getRGB(x, y);
                int alpha = (argb >>> 24) & 0xFF;
                if (alpha == 0)
                {
                    continue;
                }
                masked.setRGB(x, y, (alpha << 24) | backgroundRgb);
            }
        }

        return masked;
    }

    private Color getInventoryBackgroundColor()
    {
        return client.isResized() ? INVENTORY_BACKGROUND_RESIZABLE : INVENTORY_BACKGROUND_FIXED;
    }

    private boolean isActiveWidget(WidgetItem widgetItem, Rectangle bounds)
    {
        boolean dragging = updateDragState();
        Widget widget = widgetItem.getWidget();
        long key = widgetKey(widget);
        int cycle = client.getGameCycle();
        int itemId = widgetItem.getId();
        int quantity = widgetItem.getQuantity();

        if (isSelectedWidget(widget) || isDraggedWidget(widget))
        {
            if (!dragging)
            {
                rememberActive(key, cycle, itemId, quantity);
            }
            return true;
        }

        if (dragging)
        {
            return false;
        }

        if (client.getMouseCurrentButton() != 1)
        {
            return isRecentlyActive(key, cycle, itemId, quantity);
        }

        Point mouse = client.getMouseCanvasPosition();
        if (mouse == null)
        {
            return isRecentlyActive(key, cycle, itemId, quantity);
        }

        if (bounds.contains(mouse.getX(), mouse.getY()))
        {
            rememberActive(key, cycle, itemId, quantity);
            return true;
        }

        return isRecentlyActive(key, cycle, itemId, quantity);
    }

    private boolean isDraggedWidget(Widget widget)
    {
        Widget dragged = client.getDraggedWidget();
        if (dragged == null)
        {
            return false;
        }

        return dragged == widget
            || (dragged.getId() == widget.getId() && dragged.getIndex() == widget.getIndex());
    }

    private boolean isSelectedWidget(Widget widget)
    {
        if (!client.isWidgetSelected())
        {
            return false;
        }

        Widget selected = client.getSelectedWidget();
        if (selected == null)
        {
            return false;
        }

        return selected == widget
            || (selected.getId() == widget.getId() && selected.getIndex() == widget.getIndex());
    }

    private boolean isRecentlyActive(long key, int currentCycle, int itemId, int quantity)
    {
        ActiveState state = recentActiveStates.get(key);
        if (state == null)
        {
            return false;
        }

        if (state.itemId != itemId || state.quantity != quantity)
        {
            recentActiveStates.remove(key);
            return false;
        }

        if (currentCycle - state.lastCycle <= ACTIVE_LINGER_CYCLES)
        {
            return true;
        }

        recentActiveStates.remove(key);
        return false;
    }

    private long widgetKey(Widget widget)
    {
        return ((long) widget.getId() << 32) | (widget.getIndex() & 0xffffffffL);
    }

    private void rememberActive(long key, int cycle, int itemId, int quantity)
    {
        recentActiveStates.put(key, new ActiveState(cycle, itemId, quantity));
    }

    private boolean updateDragState()
    {
        boolean dragging = client.getDraggedWidget() != null;
        if (dragging)
        {
            recentActiveStates.clear();
            wasDragging = true;
        }
        else if (wasDragging)
        {
            recentActiveStates.clear();
            wasDragging = false;
        }
        return dragging;
    }

    private static final class ActiveState
    {
        private final int lastCycle;
        private final int itemId;
        private final int quantity;

        private ActiveState(int lastCycle, int itemId, int quantity)
        {
            this.lastCycle = lastCycle;
            this.itemId = itemId;
            this.quantity = quantity;
        }
    }

}

package com.wildyqol.misclick;

import com.wildyqol.AreaDetection;
import com.wildyqol.WildyQoLConfig;
import com.wildyqol.WildyQoLConfig.SpecialAttackOrbBlockMode;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
public class MisclickPreventionService
{
	private static final Set<Integer> RUNE_POUCH_ITEM_IDS = Set.of(
		ItemID.BH_RUNE_POUCH,
		ItemID.BH_RUNE_POUCH_TROUVER,
		ItemID.DIVINE_RUNE_POUCH,
		ItemID.DIVINE_RUNE_POUCH_TROUVER
	);
	private static final Set<Integer> SPECIAL_ATTACK_ORB_BUTTON_IDS = Set.of(
		InterfaceID.Orbs.SPECBUTTON,
		InterfaceID.OrbsNomap.SPECBUTTON,
		InterfaceID.OrbsOsm.SPECBUTTON,
		InterfaceID.OrbsOsmNomap.SPECBUTTON
	);

	private final Client client;
	private final ItemManager itemManager;
	private final WildyQoLConfig config;

	@Inject
	private MisclickPreventionService(Client client, ItemManager itemManager, WildyQoLConfig config)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.config = config;
	}

	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (config.petSpellBlocker())
		{
			handlePetSpellBlock(event);
		}
	}

	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (handleSpecialAttackOrbClick(event))
		{
			return;
		}

		if (handleRunePouchLeftClick(event))
		{
			return;
		}

		handleEmptyVialBlocker(event);
	}

	private void handlePetSpellBlock(MenuEntryAdded event)
	{
		boolean isCastOption = "Cast".equals(event.getOption());
		boolean isExamineNpc = event.getMenuEntry().getType() == MenuAction.EXAMINE_NPC;
		boolean isSpellSelected = isSpellSelected();

		if (!isCastOption && (!isSpellSelected || !isExamineNpc))
		{
			return;
		}

		int npcIndex = event.getIdentifier();
		if (npcIndex < 0)
		{
			return;
		}

		NPC npc = client.getTopLevelWorldView().npcs().byIndex(npcIndex);
		if (npc == null)
		{
			return;
		}

		NPCComposition comp = npc.getComposition();
		if (comp != null && comp.isFollower())
		{
			client.getMenu().removeMenuEntry(event.getMenuEntry());
			log.debug("Removed spell cast menu entry for pet: {}", npc.getName());
		}
	}

	private boolean isSpellSelected()
	{
		if (!client.isWidgetSelected())
		{
			return false;
		}

		Widget selectedWidget = client.getSelectedWidget();
		return selectedWidget != null
			&& WidgetUtil.componentToInterface(selectedWidget.getId()) == InterfaceID.MAGIC_SPELLBOOK;
	}

	private boolean handleSpecialAttackOrbClick(MenuOptionClicked event)
	{
		SpecialAttackOrbBlockMode mode = config.specialAttackOrbBlocker();
		if (mode == SpecialAttackOrbBlockMode.NEVER)
		{
			return false;
		}

		MenuEntry clicked = event.getMenuEntry();
		Widget widget = clicked.getWidget();
		int widgetId = widget != null ? widget.getId() : clicked.getParam1();

		if (shouldBlockSpecialAttackOrbClick(mode, mode == SpecialAttackOrbBlockMode.PVP && isInPvpArea(), widgetId))
		{
			event.consume();
			return true;
		}

		return false;
	}

	static boolean shouldBlockSpecialAttackOrbClick(SpecialAttackOrbBlockMode mode, boolean inPvpArea, int widgetId)
	{
		if (!isSpecialAttackOrbButton(widgetId))
		{
			return false;
		}

		return mode == SpecialAttackOrbBlockMode.ALWAYS
			|| mode == SpecialAttackOrbBlockMode.PVP && inPvpArea;
	}

	static boolean isSpecialAttackOrbButton(int widgetId)
	{
		return SPECIAL_ATTACK_ORB_BUTTON_IDS.contains(widgetId);
	}

	private boolean handleRunePouchLeftClick(MenuOptionClicked event)
	{
		if (!config.runePouchBlocker() || client.isMenuOpen())
		{
			return false;
		}

		if (!isInPvpArea())
		{
			return false;
		}

		MenuEntry clicked = event.getMenuEntry();
		if (!isRunePouch(clicked.getItemId()) || clicked.getType() == MenuAction.EXAMINE_ITEM)
		{
			return false;
		}

		event.consume();
		return true;
	}

	private boolean isRunePouch(int itemId)
	{
		int canonicalId = itemManager.canonicalize(itemId);
		return canonicalId > 0 && RUNE_POUCH_ITEM_IDS.contains(canonicalId);
	}

	private boolean isInPvpArea()
	{
		return AreaDetection.isMisclickPvpArea(client);
	}

	private void handleEmptyVialBlocker(MenuOptionClicked event)
	{
		if (!config.emptyVialBlocker() || !isInPvpArea())
		{
			return;
		}

		if (!"Use".equals(event.getMenuEntry().getOption()))
		{
			return;
		}

		if (event.getMenuEntry().getItemId() == ItemID.VIAL_EMPTY)
		{
			event.consume();
		}
	}
}

package com.wildyqol.persistence;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executor;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.locks.ReentrantLock;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

@Slf4j
@Singleton
public class SharedStateStore
{
	private static final int CURRENT_VERSION = 1;
	private static final String DATA_DIRECTORY = "wildy-qol";
	private static final String DATA_FILE = "shared-state.json";
	private static final String LOCK_FILE = "shared-state.lock";
	private static final ReentrantLock PROCESS_LOCK = new ReentrantLock();

	private final Gson gson;
	private final Path dataDirectory;
	private final Path dataFile;
	private final Path lockFile;
	private final Executor writer;
	private final Runnable beforeWrite;
	private final Map<PendingKey, String> pendingChanges = new ConcurrentHashMap<>();
	private final AtomicBoolean flushScheduled = new AtomicBoolean();

	@Inject
	private SharedStateStore(Gson gson)
	{
		this(
			gson,
			new java.io.File(RuneLite.RUNELITE_DIR, DATA_DIRECTORY).toPath(),
			Executors.newSingleThreadExecutor(runnable ->
			{
				Thread thread = new Thread(runnable, "wildy-qol-state-writer");
				thread.setDaemon(true);
				return thread;
			}));
	}

	SharedStateStore(Gson gson, Path dataDirectory, Executor writer)
	{
		this(gson, dataDirectory, writer, () -> { });
	}

	SharedStateStore(Gson gson, Path dataDirectory, Executor writer, Runnable beforeWrite)
	{
		this.gson = gson;
		this.dataDirectory = dataDirectory;
		this.dataFile = dataDirectory.resolve(DATA_FILE);
		this.lockFile = dataDirectory.resolve(LOCK_FILE);
		this.writer = writer;
		this.beforeWrite = beforeWrite;
	}

	public Map<String, String> readCharacter(String profileKey)
	{
		if (profileKey == null)
		{
			return Collections.emptyMap();
		}

		flush();
		SharedState state = readState();
		Map<String, String> values = state.characters.get(profileKey);
		return values == null ? Collections.emptyMap() : new HashMap<>(values);
	}

	public Map<String, String> readShared()
	{
		flush();
		return new HashMap<>(readState().shared);
	}

	public void putCharacter(String profileKey, String key, String value)
	{
		if (profileKey == null || key == null || value == null)
		{
			return;
		}

		pendingChanges.put(PendingKey.character(profileKey, key), value);
		scheduleFlush();
	}

	public void putCharacter(String profileKey, Map<String, String> values)
	{
		if (profileKey == null || values == null || values.isEmpty())
		{
			return;
		}

		boolean changed = false;
		for (Map.Entry<String, String> entry : values.entrySet())
		{
			if (entry.getKey() != null && entry.getValue() != null)
			{
				pendingChanges.put(PendingKey.character(profileKey, entry.getKey()), entry.getValue());
				changed = true;
			}
		}

		if (changed)
		{
			scheduleFlush();
		}
	}

	public void putShared(String key, String value)
	{
		if (key == null || value == null)
		{
			return;
		}

		pendingChanges.put(PendingKey.shared(key), value);
		scheduleFlush();
	}

	public void flush()
	{
		while (flushAll())
		{
			PROCESS_LOCK.lock();
			try
			{
				if (pendingChanges.isEmpty())
				{
					return;
				}
			}
			finally
			{
				PROCESS_LOCK.unlock();
			}
		}
	}

	private boolean flushAll()
	{
		while (!pendingChanges.isEmpty())
		{
			if (!flushPendingOnce())
			{
				return false;
			}
		}
		return true;
	}

	private void scheduleFlush()
	{
		if (!flushScheduled.compareAndSet(false, true))
		{
			return;
		}

		writer.execute(() ->
		{
			boolean success = false;
			try
			{
				success = flushAll();
			}
			finally
			{
				flushScheduled.set(false);
				if (success && !pendingChanges.isEmpty())
				{
					scheduleFlush();
				}
			}
		});
	}

	private boolean flushPendingOnce()
	{
		Map<PendingKey, String> changes = Collections.emptyMap();
		PROCESS_LOCK.lock();
		try
		{
			changes = drainPendingChanges();
			if (changes.isEmpty())
			{
				return true;
			}

			Files.createDirectories(dataDirectory);
			try (FileChannel channel = FileChannel.open(lockFile, StandardOpenOption.CREATE, StandardOpenOption.WRITE);
				 FileLock ignored = channel.lock())
			{
				SharedState state = readStateFile();
				for (Map.Entry<PendingKey, String> entry : changes.entrySet())
				{
					entry.getKey().apply(state, entry.getValue());
				}
				beforeWrite.run();
				writeStateFile(state);
			}
			return true;
		}
		catch (IOException | RuntimeException ex)
		{
			for (Map.Entry<PendingKey, String> entry : changes.entrySet())
			{
				pendingChanges.putIfAbsent(entry.getKey(), entry.getValue());
			}
			log.warn("Unable to save shared Wildy QoL state", ex);
			return false;
		}
		finally
		{
			PROCESS_LOCK.unlock();
		}
	}

	private Map<PendingKey, String> drainPendingChanges()
	{
		Map<PendingKey, String> drained = new HashMap<>();
		for (Map.Entry<PendingKey, String> entry : pendingChanges.entrySet())
		{
			if (pendingChanges.remove(entry.getKey(), entry.getValue()))
			{
				drained.put(entry.getKey(), entry.getValue());
			}
		}
		return drained;
	}

	private SharedState readState()
	{
		PROCESS_LOCK.lock();
		try
		{
			Files.createDirectories(dataDirectory);
			try (FileChannel channel = FileChannel.open(lockFile, StandardOpenOption.CREATE, StandardOpenOption.WRITE);
				 FileLock ignored = channel.lock())
			{
				return readStateFile();
			}
		}
		catch (IOException | RuntimeException ex)
		{
			log.warn("Unable to read shared Wildy QoL state", ex);
			return new SharedState();
		}
		finally
		{
			PROCESS_LOCK.unlock();
		}
	}

	private SharedState readStateFile() throws IOException
	{
		if (!Files.exists(dataFile))
		{
			return new SharedState();
		}

		try (Reader reader = Files.newBufferedReader(dataFile, StandardCharsets.UTF_8))
		{
			SharedState state = gson.fromJson(reader, SharedState.class);
			if (state == null || state.version != CURRENT_VERSION)
			{
				throw new UnsupportedStateVersionException(state == null ? null : state.version);
			}
			state.normalize();
			return state;
		}
		catch (JsonParseException ex)
		{
			log.warn("Unable to parse shared Wildy QoL state", ex);
			return new SharedState();
		}
	}

	private void writeStateFile(SharedState state) throws IOException
	{
		Path temporaryFile = Files.createTempFile(dataDirectory, "shared-state-", ".tmp");
		try
		{
			try (Writer output = Files.newBufferedWriter(
				temporaryFile,
				StandardCharsets.UTF_8,
				StandardOpenOption.TRUNCATE_EXISTING))
			{
				gson.toJson(state, output);
			}

			try
			{
				Files.move(
					temporaryFile,
					dataFile,
					StandardCopyOption.ATOMIC_MOVE,
					StandardCopyOption.REPLACE_EXISTING);
			}
			catch (AtomicMoveNotSupportedException ex)
			{
				Files.move(temporaryFile, dataFile, StandardCopyOption.REPLACE_EXISTING);
			}
		}
		finally
			{
				Files.deleteIfExists(temporaryFile);
			}
		}

	private static final class UnsupportedStateVersionException extends IOException
	{
		private UnsupportedStateVersionException(Integer version)
		{
			super("Unsupported shared Wildy QoL state version: " + version);
		}
	}

	private static final class SharedState
	{
		private int version = CURRENT_VERSION;
		private Map<String, Map<String, String>> characters = new HashMap<>();
		private Map<String, String> shared = new HashMap<>();

		private void normalize()
		{
			if (characters == null)
			{
				characters = new HashMap<>();
			}
			if (shared == null)
			{
				shared = new HashMap<>();
			}
		}
	}

	private static final class PendingKey
	{
		private final String profileKey;
		private final String key;

		private PendingKey(String profileKey, String key)
		{
			this.profileKey = profileKey;
			this.key = key;
		}

		private static PendingKey character(String profileKey, String key)
		{
			return new PendingKey(profileKey, key);
		}

		private static PendingKey shared(String key)
		{
			return new PendingKey(null, key);
		}

		private void apply(SharedState state, String value)
		{
			if (profileKey == null)
			{
				state.shared.put(key, value);
				return;
			}

			state.characters.computeIfAbsent(profileKey, ignored -> new HashMap<>()).put(key, value);
		}

		@Override
		public boolean equals(Object other)
		{
			if (this == other)
			{
				return true;
			}
			if (!(other instanceof PendingKey))
			{
				return false;
			}
			PendingKey that = (PendingKey) other;
			return Objects.equals(profileKey, that.profileKey) && key.equals(that.key);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(profileKey, key);
		}
	}
}

package com.wildyqol.prayer;

enum PrayerLayoutBuild
{
	PURE("Pure", "prayerLayoutPure"),
	ZERKER("Zerker", "prayerLayoutZerker"),
	MAX_MED("Max/Med", "prayerLayoutMaxMed");

	private final String displayName;
	private final String storageKey;

	PrayerLayoutBuild(String displayName, String storageKey)
	{
		this.displayName = displayName;
		this.storageKey = storageKey;
	}

	static PrayerLayoutBuild fromLmsDefence(int defenceLevel)
	{
		if (defenceLevel <= 1)
		{
			return PURE;
		}

		if (defenceLevel <= 50)
		{
			return ZERKER;
		}

		return MAX_MED;
	}

	static PrayerLayoutBuild fromPvpArenaVarbit(int value)
	{
		switch (value)
		{
			case 0:
				return MAX_MED;
			case 1:
				return ZERKER;
			case 2:
				return PURE;
			default:
				return null;
		}
	}

	String getDisplayName()
	{
		return displayName;
	}

	String getStorageKey()
	{
		return storageKey;
	}
}

package com.wildyqol.prayer;

final class PrayerLayoutCaptureGate
{
	private long activeProfileId;
	private long generation;
	private boolean active;

	synchronized void activate(long profileId)
	{
		activeProfileId = profileId;
		active = true;
		generation++;
	}

	synchronized void invalidate()
	{
		active = false;
		generation++;
	}

	synchronized Token token(long profileId)
	{
		return active && profileId == activeProfileId
			? new Token(profileId, generation)
			: null;
	}

	synchronized boolean isCurrent(Token token, long profileId)
	{
		return token != null
			&& active
			&& token.profileId == activeProfileId
			&& token.profileId == profileId
			&& token.generation == generation;
	}

	static final class Token
	{
		private final long profileId;
		private final long generation;

		private Token(long profileId, long generation)
		{
			this.profileId = profileId;
			this.generation = generation;
		}
	}
}

package com.wildyqol.prayer;

import java.util.Objects;

final class PrayerLayoutContext
{
	private final String profileKey;
	private final String characterName;
	private final PrayerLayoutBuild build;

	private PrayerLayoutContext(String profileKey, String characterName, PrayerLayoutBuild build)
	{
		this.profileKey = profileKey;
		this.characterName = characterName;
		this.build = build;
	}

	static PrayerLayoutContext account(String profileKey, String characterName)
	{
		return new PrayerLayoutContext(Objects.requireNonNull(profileKey), characterName, null);
	}

	static PrayerLayoutContext minigame(PrayerLayoutBuild build)
	{
		return new PrayerLayoutContext(null, null, Objects.requireNonNull(build));
	}

	boolean isAccount()
	{
		return profileKey != null;
	}

	String getProfileKey()
	{
		return profileKey;
	}

	String getStorageKey()
	{
		return isAccount() ? PrayerLayoutStore.ACCOUNT_STORAGE_KEY : build.getStorageKey();
	}

	String getRestoreMessage(boolean hideRsn)
	{
		if (isAccount())
		{
			if (hideRsn)
			{
				return "Wildy QoL: Prayer layout restored.";
			}

			String name = characterName == null || characterName.isEmpty() ? "this character" : characterName;
			return "Wildy QoL: Prayer layout restored for " + name + ".";
		}

		return "Wildy QoL: Prayer layout restored for the "
			+ build.getDisplayName() + " LMS / PvP Arena setup.";
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}

		if (!(other instanceof PrayerLayoutContext))
		{
			return false;
		}

		PrayerLayoutContext that = (PrayerLayoutContext) other;
		return Objects.equals(profileKey, that.profileKey) && build == that.build;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(profileKey, build);
	}
}

package com.wildyqol.prayer;

final class PrayerLayoutContextResolver
{
	private PrayerLayoutBuild latchedLmsBuild;

	PrayerLayoutContext resolve(
		String profileKey,
		String characterName,
		boolean activeLms,
		boolean allowLmsClassification,
		int defenceLevel,
		boolean activePvpArena,
		int pvpArenaBuildVarbit)
	{
		if (!activeLms)
		{
			latchedLmsBuild = null;
		}

		if (activeLms)
		{
			if (latchedLmsBuild == null && allowLmsClassification)
			{
				latchedLmsBuild = PrayerLayoutBuild.fromLmsDefence(defenceLevel);
			}

			return latchedLmsBuild == null ? null : PrayerLayoutContext.minigame(latchedLmsBuild);
		}

		if (activePvpArena)
		{
			PrayerLayoutBuild build = PrayerLayoutBuild.fromPvpArenaVarbit(pvpArenaBuildVarbit);
			return build == null ? null : PrayerLayoutContext.minigame(build);
		}

		return profileKey == null ? null : PrayerLayoutContext.account(profileKey, characterName);
	}

	void reset()
	{
		latchedLmsBuild = null;
	}
}

package com.wildyqol.prayer;

final class PrayerLayoutCoordinator
{
	interface Backend
	{
		PrayerLayoutSnapshot capture();

		PrayerLayoutSnapshot load(PrayerLayoutContext context);

		void save(PrayerLayoutContext context, PrayerLayoutSnapshot snapshot);

		boolean apply(PrayerLayoutSnapshot target, PrayerLayoutSnapshot current);

		void restored(PrayerLayoutContext context);
	}

	private final Backend backend;
	private PrayerLayoutContext currentContext;
	private PrayerLayoutSnapshot persistedSnapshot;

	PrayerLayoutCoordinator(Backend backend)
	{
		this.backend = backend;
	}

	void transitionTo(PrayerLayoutContext nextContext)
	{
		if (nextContext == null || nextContext.equals(currentContext))
		{
			return;
		}

		saveCurrent();

		PrayerLayoutSnapshot current = backend.capture();
		PrayerLayoutSnapshot saved = backend.load(nextContext);
		currentContext = nextContext;

		if (saved == null)
		{
			backend.save(nextContext, current);
			persistedSnapshot = current;
			return;
		}

		persistedSnapshot = saved;
		if (!saved.equals(current) && backend.apply(saved, current))
		{
			backend.restored(nextContext);
		}
	}

	void saveCurrent()
	{
		if (currentContext != null)
		{
			PrayerLayoutSnapshot current = backend.capture();
			if (!current.equals(persistedSnapshot))
			{
				backend.save(currentContext, current);
				persistedSnapshot = current;
			}
		}
	}

	void leaveCurrent()
	{
		saveCurrent();
		currentContext = null;
		persistedSnapshot = null;
	}

	void clear()
	{
		currentContext = null;
		persistedSnapshot = null;
	}
}

package com.wildyqol.prayer;

import com.wildyqol.AreaDetection;
import com.wildyqol.WildyQoLConfig;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.ConfigProfile;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.prayer.PrayerPlugin;

@Singleton
public class PrayerLayoutService implements PrayerLayoutCoordinator.Backend
{
	private static final String PRAYER_CONFIG_GROUP = "prayer";
	private static final String ORDER_KEY_PREFIX = "prayer_order_book";
	private static final String HIDDEN_KEY_PREFIX = "prayer_hidden_book";
	private static final String PERSIST_CONFIG_KEY = "persistPrayerLayout";

	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final PluginManager pluginManager;
	private final ChatMessageManager chatMessageManager;
	private final WildyQoLConfig config;
	private final PrayerLayoutStore store;
	private final PrayerLayoutContextResolver contextResolver = new PrayerLayoutContextResolver();
	private final PrayerLayoutCoordinator coordinator;
	private final PrayerLayoutCaptureGate captureGate = new PrayerLayoutCaptureGate();
	private final AtomicBoolean captureScheduled = new AtomicBoolean();

	private volatile boolean applyingLayout;
	private boolean prayerPluginActive;

	@Inject
	private PrayerLayoutService(
		Client client,
		ClientThread clientThread,
		ConfigManager configManager,
		PluginManager pluginManager,
		ChatMessageManager chatMessageManager,
		WildyQoLConfig config,
		PrayerLayoutStore store)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.pluginManager = pluginManager;
		this.chatMessageManager = chatMessageManager;
		this.config = config;
		this.store = store;
		this.coordinator = new PrayerLayoutCoordinator(this);
	}

	public void startUp()
	{
		clientThread.invokeLater(() ->
		{
			captureGate.activate(getConfigProfileId());
			prayerPluginActive = isCorePrayerPluginActive();
			contextResolver.reset();
			coordinator.clear();
			reconcile(false);
		});
	}

	public void shutDown()
	{
		captureGate.invalidate();
		clientThread.invokeLater(() ->
		{
			if (config.persistPrayerReordering() && prayerPluginActive)
			{
				restoreAccountAndClear();
			}
			else
			{
				coordinator.clear();
			}
			store.flush();
			contextResolver.reset();
			prayerPluginActive = false;
		});
	}

	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			reconcile(false);
		}
		else if (config.persistPrayerReordering() && prayerPluginActive)
		{
			coordinator.leaveCurrent();
			store.flush();
			contextResolver.reset();
		}
	}

	public void onGameTick()
	{
		reconcile(true);
	}

	public void onVarbitChanged(VarbitChanged event)
	{
		int varbitId = event.getVarbitId();
		if (varbitId == VarbitID.BR_INGAME
			|| varbitId == VarbitID.PVPA_BATTLEAREA_STATUS
			|| varbitId == VarbitID.PVPA_TRANSMIT_BUILD)
		{
			reconcile(false);
		}
	}

	public void onRuneScapeProfileChanged()
	{
		reconcile(false);
	}

	public void onProfileChanged()
	{
		captureGate.invalidate();
		clientThread.invokeLater(() ->
		{
			coordinator.clear();
			contextResolver.reset();
			captureGate.activate(getConfigProfileId());
			prayerPluginActive = isCorePrayerPluginActive();
			reconcile(false);
		});
	}

	public void onPluginChanged(PluginChanged event)
	{
		if (!(event.getPlugin() instanceof PrayerPlugin))
		{
			return;
		}

		captureGate.invalidate();
		clientThread.invokeLater(() ->
		{
			if (!event.isLoaded() && config.persistPrayerReordering() && prayerPluginActive)
			{
				restoreAccountAndClear();
			}
			else
			{
				coordinator.clear();
			}

			prayerPluginActive = event.isLoaded();
			contextResolver.reset();
			if (prayerPluginActive)
			{
				captureGate.activate(getConfigProfileId());
				reconcile(false);
			}
		});
	}

	public void onConfigChanged(ConfigChanged event)
	{
		if (PrayerLayoutStore.CONFIG_GROUP.equals(event.getGroup())
			&& PERSIST_CONFIG_KEY.equals(event.getKey()))
		{
			captureGate.invalidate();
			clientThread.invokeLater(() ->
			{
				prayerPluginActive = isCorePrayerPluginActive();
				if (!config.persistPrayerReordering() && prayerPluginActive)
				{
					restoreAccountAndClear();
				}
				else
				{
					coordinator.clear();
				}
				contextResolver.reset();
				if (config.persistPrayerReordering())
				{
					captureGate.activate(getConfigProfileId());
					reconcile(false);
				}
			});
			return;
		}

		if (!PRAYER_CONFIG_GROUP.equals(event.getGroup())
			|| !PrayerLayoutSnapshot.isLayoutKey(event.getKey())
			|| applyingLayout
			|| !config.persistPrayerReordering()
			|| !prayerPluginActive)
		{
			return;
		}

		PrayerLayoutCaptureGate.Token captureToken = captureGate.token(getConfigProfileId());
		if (captureToken != null && captureScheduled.compareAndSet(false, true))
		{
			clientThread.invokeLater(() ->
			{
				captureScheduled.set(false);
				if (!applyingLayout
					&& config.persistPrayerReordering()
					&& prayerPluginActive
					&& captureGate.isCurrent(captureToken, getConfigProfileId()))
				{
					coordinator.saveCurrent();
				}
			});
		}
	}

	private long getConfigProfileId()
	{
		ConfigProfile profile = configManager.getProfile();
		return profile == null ? Long.MIN_VALUE : profile.getId();
	}

	private void reconcile(boolean allowLmsClassification)
	{
		if (!config.persistPrayerReordering()
			|| !prayerPluginActive
			|| client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		boolean activeLms = AreaDetection.isActiveLmsGame(client);
		PrayerLayoutContext context = contextResolver.resolve(
			configManager.getRSProfileKey(),
			getCharacterName(),
			activeLms,
			allowLmsClassification,
			activeLms ? client.getBoostedSkillLevel(Skill.DEFENCE) : 0,
			AreaDetection.isPvpArenaMatch(client),
			client.getVarbitValue(VarbitID.PVPA_TRANSMIT_BUILD));

		coordinator.transitionTo(context);
	}

	private String getCharacterName()
	{
		String profileName = configManager.getRSProfileConfiguration(
			ConfigManager.RSPROFILE_GROUP,
			ConfigManager.RSPROFILE_DISPLAY_NAME,
			String.class);
		if (profileName != null && !profileName.isEmpty())
		{
			return profileName;
		}

		Player localPlayer = client.getLocalPlayer();
		return localPlayer == null ? null : localPlayer.getName();
	}

	private void restoreAccountAndClear()
	{
		String profileKey = configManager.getRSProfileKey();
		if (profileKey == null)
		{
			coordinator.saveCurrent();
			coordinator.clear();
			return;
		}

		coordinator.transitionTo(PrayerLayoutContext.account(profileKey, getCharacterName()));
		coordinator.clear();
	}

	private boolean isCorePrayerPluginActive()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (plugin instanceof PrayerPlugin)
			{
				return pluginManager.isPluginActive(plugin);
			}
		}

		return false;
	}

	@Override
	public PrayerLayoutSnapshot capture()
	{
		Map<String, String> values = new TreeMap<>();
		captureKeys(ORDER_KEY_PREFIX, values);
		captureKeys(HIDDEN_KEY_PREFIX, values);
		return new PrayerLayoutSnapshot(values);
	}

	private void captureKeys(String prefix, Map<String, String> values)
	{
		for (String wholeKey : configManager.getConfigurationKeys(PRAYER_CONFIG_GROUP + "." + prefix))
		{
			int separator = wholeKey.indexOf('.');
			if (separator < 0 || !PRAYER_CONFIG_GROUP.equals(wholeKey.substring(0, separator)))
			{
				continue;
			}

			String key = wholeKey.substring(separator + 1);
			String value = configManager.getConfiguration(PRAYER_CONFIG_GROUP, key);
			if (PrayerLayoutSnapshot.isLayoutKey(key) && value != null)
			{
				values.put(key, value);
			}
		}
	}

	@Override
	public PrayerLayoutSnapshot load(PrayerLayoutContext context)
	{
		return store.load(context);
	}

	@Override
	public void save(PrayerLayoutContext context, PrayerLayoutSnapshot snapshot)
	{
		store.save(context, snapshot);
	}

	@Override
	public boolean apply(PrayerLayoutSnapshot target, PrayerLayoutSnapshot current)
	{
		if (!prayerPluginActive)
		{
			return false;
		}

		Map<String, String> targetValues = target.getValues();
		Map<String, String> currentValues = current.getValues();
		boolean changed = false;
		applyingLayout = true;
		try
		{
			for (String key : currentValues.keySet())
			{
				if (!targetValues.containsKey(key))
				{
					configManager.unsetConfiguration(PRAYER_CONFIG_GROUP, key);
					changed = true;
				}
			}

			for (Map.Entry<String, String> entry : targetValues.entrySet())
			{
				if (!entry.getValue().equals(currentValues.get(entry.getKey())))
				{
					configManager.setConfiguration(PRAYER_CONFIG_GROUP, entry.getKey(), entry.getValue());
					changed = true;
				}
			}
		}
		finally
		{
			applyingLayout = false;
		}

		if (changed)
		{
			redrawPrayers();
		}
		return changed;
	}

	private void redrawPrayers()
	{
		Widget prayerBook = client.getWidget(InterfaceID.PRAYERBOOK, 0);
		if (prayerBook != null && prayerBook.getOnVarTransmitListener() != null)
		{
			client.runScript(prayerBook.getOnVarTransmitListener());
		}
	}

	@Override
	public void restored(PrayerLayoutContext context)
	{
		if (!config.gameMessageOnPrayerReordering() || !prayerPluginActive)
		{
			return;
		}

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(context.getRestoreMessage(config.hideRsnInPrayerLayoutMessage()))
			.build());
	}
}

package com.wildyqol.prayer;

import java.util.Collections;
import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;

final class PrayerLayoutSnapshot
{
	static final int CURRENT_VERSION = 1;
	private static final String ORDER_PREFIX = "prayer_order_book_";
	private static final String HIDDEN_PREFIX = "prayer_hidden_book_";

	private int version;
	private Map<String, String> values;

	@SuppressWarnings("unused")
	private PrayerLayoutSnapshot()
	{
	}

	PrayerLayoutSnapshot(Map<String, String> values)
	{
		this.version = CURRENT_VERSION;
		this.values = sanitized(values);
	}

	boolean isSupportedVersion()
	{
		return version == CURRENT_VERSION && values != null;
	}

	Map<String, String> getValues()
	{
		return Collections.unmodifiableMap(sanitized(values));
	}

	static boolean isLayoutKey(String key)
	{
		return key != null && (key.startsWith(ORDER_PREFIX) || key.startsWith(HIDDEN_PREFIX));
	}

	private static Map<String, String> sanitized(Map<String, String> source)
	{
		Map<String, String> result = new TreeMap<>();
		if (source == null)
		{
			return result;
		}

		for (Map.Entry<String, String> entry : source.entrySet())
		{
			if (isLayoutKey(entry.getKey()) && entry.getValue() != null)
			{
				result.put(entry.getKey(), entry.getValue());
			}
		}

		return result;
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}

		if (!(other instanceof PrayerLayoutSnapshot))
		{
			return false;
		}

		PrayerLayoutSnapshot that = (PrayerLayoutSnapshot) other;
		return getValues().equals(that.getValues());
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(getValues());
	}
}

package com.wildyqol.prayer;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.wildyqol.persistence.SharedStateStore;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
final class PrayerLayoutStore
{
	static final String CONFIG_GROUP = "wildyqol";
	static final String ACCOUNT_STORAGE_KEY = "prayerLayoutAccount";
	private static final String SHARED_CHARACTER_KEY = "prayer.layout";
	private static final String SHARED_LAYOUT_PREFIX = "prayer.";

	private final Gson gson;
	private final SharedStateStore sharedStateStore;

	@Inject
	PrayerLayoutStore(Gson gson, SharedStateStore sharedStateStore)
	{
		this.gson = gson;
		this.sharedStateStore = sharedStateStore;
	}

	PrayerLayoutSnapshot load(PrayerLayoutContext context)
	{
		Map<String, String> sharedState = context.isAccount()
			? sharedStateStore.readCharacter(context.getProfileKey())
			: sharedStateStore.readShared();
		return parse(sharedState.get(sharedKey(context)));
	}

	private PrayerLayoutSnapshot parse(String json)
	{
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			PrayerLayoutSnapshot snapshot = gson.fromJson(json, PrayerLayoutSnapshot.class);
			if (snapshot != null && snapshot.isSupportedVersion())
			{
				return new PrayerLayoutSnapshot(snapshot.getValues());
			}
		}
		catch (JsonParseException ex)
		{
			log.warn("Unable to read saved prayer layout", ex);
		}

		return null;
	}

	void save(PrayerLayoutContext context, PrayerLayoutSnapshot snapshot)
	{
		String json = gson.toJson(snapshot);
		writeShared(context, sharedKey(context), json);
	}

	void flush()
	{
		sharedStateStore.flush();
	}

	private String sharedKey(PrayerLayoutContext context)
	{
		return context.isAccount() ? SHARED_CHARACTER_KEY : SHARED_LAYOUT_PREFIX + context.getStorageKey();
	}

	private void writeShared(PrayerLayoutContext context, String key, String value)
	{
		if (context.isAccount())
		{
			sharedStateStore.putCharacter(context.getProfileKey(), key, value);
		}
		else
		{
			sharedStateStore.putShared(key, value);
		}
	}
}

