package com.wildyqol.pvparena;

enum PvpArenaBuild
{
	MAIN,
	ZERK,
	PURE;

	static PvpArenaBuild fromVarbit(int value)
	{
		switch (value)
		{
			case 0:
				return MAIN;
			case 1:
				return ZERK;
			case 2:
				return PURE;
			default:
				return null;
		}
	}
}

package com.wildyqol.pvparena;

enum PvpArenaSpellbook
{
	STANDARD,
	ANCIENT,
	LUNAR;

	static PvpArenaSpellbook fromOwnVarbit(int value)
	{
		switch (value)
		{
			case 0:
				return ANCIENT;
			case 1:
				return STANDARD;
			case 2:
				return LUNAR;
			default:
				return null;
		}
	}

	static PvpArenaSpellbook fromOpponentVarbit(int value)
	{
		switch (value)
		{
			case 0:
				return STANDARD;
			case 1:
				return ANCIENT;
			case 2:
				return LUNAR;
			default:
				return null;
		}
	}
}

package com.wildyqol.pvparena;

public class PvpArenaSpellbookWarning
{
	private static final PvpArenaSpellbookWarning NONE = new PvpArenaSpellbookWarning(null, false, false);

	private final PvpArenaBuild activeBuild;
	private final boolean ownSpellbookOffending;
	private final boolean opponentSpellbookOffending;

	private PvpArenaSpellbookWarning(
		PvpArenaBuild activeBuild,
		boolean ownSpellbookOffending,
		boolean opponentSpellbookOffending)
	{
		this.activeBuild = activeBuild;
		this.ownSpellbookOffending = ownSpellbookOffending;
		this.opponentSpellbookOffending = opponentSpellbookOffending;
	}

	static PvpArenaSpellbookWarning none()
	{
		return NONE;
	}

	static PvpArenaSpellbookWarning of(
		PvpArenaBuild activeBuild,
		boolean ownSpellbookOffending,
		boolean opponentSpellbookOffending)
	{
		if (!ownSpellbookOffending && !opponentSpellbookOffending)
		{
			return NONE;
		}

		return new PvpArenaSpellbookWarning(activeBuild, ownSpellbookOffending, opponentSpellbookOffending);
	}

	public boolean hasWarning()
	{
		return ownSpellbookOffending || opponentSpellbookOffending;
	}

	PvpArenaBuild getActiveBuild()
	{
		return activeBuild;
	}

	public boolean isOwnSpellbookOffending()
	{
		return ownSpellbookOffending;
	}

	public boolean isOpponentSpellbookOffending()
	{
		return opponentSpellbookOffending;
	}
}

package com.wildyqol.pvparena;

import com.wildyqol.WildyQoLConfig.PvpArenaSpellbookWarningMode;

public class PvpArenaSpellbookWarningEvaluator
{
	public PvpArenaSpellbookWarning evaluate(
		PvpArenaSpellbookWarningMode mode,
		int activeBuildVarbit,
		int mainSpellbookVarbit,
		int zerkSpellbookVarbit,
		int pureSpellbookVarbit,
		int opponentSpellbookVarbit)
	{
		if (mode == null || mode == PvpArenaSpellbookWarningMode.NEVER)
		{
			return PvpArenaSpellbookWarning.none();
		}

		PvpArenaBuild activeBuild = PvpArenaBuild.fromVarbit(activeBuildVarbit);
		if (activeBuild == null)
		{
			return PvpArenaSpellbookWarning.none();
		}

		PvpArenaSpellbook ownSpellbook = ownSpellbook(activeBuild, mainSpellbookVarbit, zerkSpellbookVarbit, pureSpellbookVarbit);
		PvpArenaSpellbook opponentSpellbook = PvpArenaSpellbook.fromOpponentVarbit(opponentSpellbookVarbit);
		if (ownSpellbook == null || opponentSpellbook == null)
		{
			return PvpArenaSpellbookWarning.none();
		}

		if (mode == PvpArenaSpellbookWarningMode.PLAYERS_MATCH)
		{
			boolean mismatch = ownSpellbook != opponentSpellbook;
			return PvpArenaSpellbookWarning.of(activeBuild, mismatch, mismatch);
		}

		PvpArenaSpellbook targetSpellbook = targetSpellbook(mode);
		if (targetSpellbook == null)
		{
			return PvpArenaSpellbookWarning.none();
		}

		return PvpArenaSpellbookWarning.of(
			activeBuild,
			ownSpellbook != targetSpellbook,
			opponentSpellbook != targetSpellbook);
	}

	private PvpArenaSpellbook ownSpellbook(
		PvpArenaBuild activeBuild,
		int mainSpellbookVarbit,
		int zerkSpellbookVarbit,
		int pureSpellbookVarbit)
	{
		switch (activeBuild)
		{
			case MAIN:
				return PvpArenaSpellbook.fromOwnVarbit(mainSpellbookVarbit);
			case ZERK:
				return PvpArenaSpellbook.fromOwnVarbit(zerkSpellbookVarbit);
			case PURE:
				return PvpArenaSpellbook.fromOwnVarbit(pureSpellbookVarbit);
			default:
				return null;
		}
	}

	private PvpArenaSpellbook targetSpellbook(PvpArenaSpellbookWarningMode mode)
	{
		switch (mode)
		{
			case STANDARD:
				return PvpArenaSpellbook.STANDARD;
			case ANCIENT:
				return PvpArenaSpellbook.ANCIENT;
			case LUNAR:
				return PvpArenaSpellbook.LUNAR;
			default:
				return null;
		}
	}
}

package com.wildyqol.pvparena;

import com.wildyqol.WildyQoLConfig;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Singleton
public class PvpArenaSpellbookWarningOverlay extends Overlay
{
	private static final Color HIGHLIGHT_COLOR = Color.RED;
	private static final float HIGHLIGHT_STROKE_WIDTH = 2.0f;
	private static final int HIGHLIGHT_PADDING = 2;

	private final Client client;
	private final WildyQoLConfig config;
	private final PvpArenaSpellbookWarningEvaluator evaluator = new PvpArenaSpellbookWarningEvaluator();

	@Inject
	private PvpArenaSpellbookWarningOverlay(Client client, WildyQoLConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (config.pvpArenaSpellbookWarningMode() == WildyQoLConfig.PvpArenaSpellbookWarningMode.NEVER
			|| !isPvpArenaLoadoutInterfaceVisible())
		{
			return null;
		}

		if (config.pvpArenaSpellbookWarningMode() == WildyQoLConfig.PvpArenaSpellbookWarningMode.PLAYERS_MATCH
			&& !isOpponentSpellbookVisible())
		{
			return null;
		}

		PvpArenaSpellbookWarning warning = evaluator.evaluate(
			config.pvpArenaSpellbookWarningMode(),
			client.getVarbitValue(VarbitID.PVPA_TRANSMIT_BUILD),
			client.getVarbitValue(VarbitID.PVPA_LOADOUT_A_SPELLBOOK),
			client.getVarbitValue(VarbitID.PVPA_LOADOUT_B_SPELLBOOK),
			client.getVarbitValue(VarbitID.PVPA_LOADOUT_C_SPELLBOOK),
			client.getVarbitValue(VarbitID.PVPA_UNRANKEDDUEL_TRANSMIT_OPPONENTSPELLBOOK));

		if (!warning.hasWarning())
		{
			return null;
		}

		if (warning.isOwnSpellbookOffending())
		{
			drawWidgetHighlight(graphics, activeOwnSpellbookDisplay(warning.getActiveBuild()));
			if (isOpponentKitVisible())
			{
				drawWidgetHighlight(graphics, activeBuildTab(warning.getActiveBuild()));
			}
		}

		if (warning.isOpponentSpellbookOffending())
		{
			drawWidgetHighlight(graphics, visibleWidget(InterfaceID.PvpArenaUnrankedduel.OPPONENTSPELLBOOK_DISPLAY));
		}

		return null;
	}

	private boolean isPvpArenaLoadoutInterfaceVisible()
	{
		return isWidgetVisible(InterfaceID.PvpArenaStagingareaShareloadout.CONTENTS)
			|| isWidgetVisible(InterfaceID.PvpArenaStagingareaSupplies.CONTENTS)
			|| isWidgetVisible(InterfaceID.PvpArenaUnrankedduel.CONTENTS);
	}

	private boolean isOpponentKitVisible()
	{
		return isWidgetVisible(InterfaceID.PvpArenaUnrankedduel.OPPONENT)
			|| isWidgetVisible(InterfaceID.PvpArenaUnrankedduel.OPPONENTSPELLBOOK_DISPLAY);
	}

	private boolean isOpponentSpellbookVisible()
	{
		return isWidgetVisible(InterfaceID.PvpArenaUnrankedduel.OPPONENTSPELLBOOK_DISPLAY);
	}

	private Widget activeOwnSpellbookDisplay(PvpArenaBuild build)
	{
		Widget stagingDisplay = activeStagingSpellbookDisplay(build);
		if (stagingDisplay != null)
		{
			return stagingDisplay;
		}

		return activeUnrankedSpellbookDisplay(build);
	}

	private Widget activeStagingSpellbookDisplay(PvpArenaBuild build)
	{
		switch (build)
		{
			case MAIN:
				return visibleWidget(InterfaceID.PvpArenaStagingareaSupplies._0SPELLBOOK_DISPLAY);
			case ZERK:
				return visibleWidget(InterfaceID.PvpArenaStagingareaSupplies._1SPELLBOOK_DISPLAY);
			case PURE:
				return visibleWidget(InterfaceID.PvpArenaStagingareaSupplies._2SPELLBOOK_DISPLAY);
			default:
				return null;
		}
	}

	private Widget activeUnrankedSpellbookDisplay(PvpArenaBuild build)
	{
		switch (build)
		{
			case MAIN:
				return visibleWidget(InterfaceID.PvpArenaUnrankedduel._0SPELLBOOK_DISPLAY);
			case ZERK:
				return visibleWidget(InterfaceID.PvpArenaUnrankedduel._1SPELLBOOK_DISPLAY);
			case PURE:
				return visibleWidget(InterfaceID.PvpArenaUnrankedduel._2SPELLBOOK_DISPLAY);
			default:
				return null;
		}
	}

	private Widget activeBuildTab(PvpArenaBuild build)
	{
		Widget shareLoadoutTab = activeShareLoadoutBuildTab(build);
		if (shareLoadoutTab != null)
		{
			return shareLoadoutTab;
		}

		Widget stagingTab = activeStagingBuildTab(build);
		if (stagingTab != null)
		{
			return stagingTab;
		}

		return visibleWidget(InterfaceID.PvpArenaUnrankedduel.TAB_MYEQUIPMENT);
	}

	private Widget activeShareLoadoutBuildTab(PvpArenaBuild build)
	{
		switch (build)
		{
			case MAIN:
				return visibleWidget(InterfaceID.PvpArenaStagingareaShareloadout.TAB_EQUIPMENT0);
			case ZERK:
				return visibleWidget(InterfaceID.PvpArenaStagingareaShareloadout.TAB_EQUIPMENT1);
			case PURE:
				return visibleWidget(InterfaceID.PvpArenaStagingareaShareloadout.TAB_EQUIPMENT2);
			default:
				return null;
		}
	}

	private Widget activeStagingBuildTab(PvpArenaBuild build)
	{
		switch (build)
		{
			case MAIN:
				return visibleWidget(InterfaceID.PvpArenaStagingareaSupplies.TAB_EQUIPMENT0);
			case ZERK:
				return visibleWidget(InterfaceID.PvpArenaStagingareaSupplies.TAB_EQUIPMENT1);
			case PURE:
				return visibleWidget(InterfaceID.PvpArenaStagingareaSupplies.TAB_EQUIPMENT2);
			default:
				return null;
		}
	}

	private void drawWidgetHighlight(Graphics2D graphics, Widget widget)
	{
		if (widget == null)
		{
			return;
		}

		Rectangle bounds = widget.getBounds();
		if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
		{
			return;
		}

		Stroke previousStroke = graphics.getStroke();
		Color previousColor = graphics.getColor();
		graphics.setStroke(new BasicStroke(HIGHLIGHT_STROKE_WIDTH));
		graphics.setColor(HIGHLIGHT_COLOR);
		graphics.drawRect(
			bounds.x - HIGHLIGHT_PADDING,
			bounds.y - HIGHLIGHT_PADDING,
			bounds.width + HIGHLIGHT_PADDING * 2,
			bounds.height + HIGHLIGHT_PADDING * 2);
		graphics.setStroke(previousStroke);
		graphics.setColor(previousColor);
	}

	private Widget visibleWidget(int widgetId)
	{
		Widget widget = client.getWidget(widgetId);
		if (widget == null || widget.isHidden())
		{
			return null;
		}

		return widget;
	}

	private boolean isWidgetVisible(int widgetId)
	{
		return visibleWidget(widgetId) != null;
	}
}

package com.wildyqol.scenery;

import com.wildyqol.WildyQoLConfig;
import com.wildyqol.AreaDetection;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.events.ConfigChanged;

@Singleton
public class EmirsArenaSceneryService
{
	private static final int MARKER_REGION_BASE_X = 3328; // Region 13384, x region 52.
	private static final int MARKER_REGION_BASE_Y = 4608; // Region 13384, y region 72.
	private static final TileRectangle OUTER_HIDE_RECT = new TileRectangle(17, 28, 50, 49);
	private static final TileRectangle INNER_KEEP_RECT = new TileRectangle(23, 31, 44, 45);
	private static final Set<TileRectangle> EXCLUDE_RECTS = Set.of(
		new TileRectangle(22, 37, 23, 39), // W gate
		new TileRectangle(44, 37, 45, 39)  // E gate
	);

	private final RenderCallback renderCallback = new RenderCallback()
	{
		@Override
		public boolean drawObject(Scene scene, TileObject object)
		{
			return true;
		}

		@Override
		public boolean drawTile(Scene scene, Tile tile)
		{
			return shouldDrawTile(scene, tile);
		}
	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private RenderCallbackManager renderCallbackManager;

	@Inject
	private WildyQoLConfig config;

	private volatile boolean removeObstructingScenery;
	private volatile boolean inPvpArea;

	public void startUp()
	{
		updateConfig();
		renderCallbackManager.register(renderCallback);
		clientThread.invoke(() -> inPvpArea = isInPvpArea());
	}

	public void shutDown()
	{
		renderCallbackManager.unregister(renderCallback);
	}

	public void onConfigChanged(ConfigChanged event)
	{
		if (!"wildyqol".equals(event.getGroup()) || !"removeObstructingPvpArenaScenery".equals(event.getKey()))
		{
			return;
		}

		reloadSceneWithCurrentFightState();
	}

	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() != VarbitID.INSIDE_WILDERNESS && event.getVarbitId() != VarbitID.PVP_AREA_CLIENT)
		{
			return;
		}

		boolean nowInPvpArea = isInPvpArea();
		if (inPvpArea == nowInPvpArea)
		{
			return;
		}

		inPvpArea = nowInPvpArea;
		if (shouldRemoveArenaScenery())
		{
			reloadScene();
		}
	}

	private boolean shouldDrawTile(Scene scene, Tile tile)
	{
		if (!shouldRemoveArenaScenery() || !inPvpArea || tile == null || tile.getLocalLocation() == null || !isRemovedWallTile(scene, tile))
		{
			return true;
		}

		scene.removeTile(tile);
		return false;
	}

	private boolean isRemovedWallTile(Scene scene, Tile tile)
	{
		try
		{
			WorldPoint templateLocation = WorldPoint.fromLocalInstance(scene, tile.getLocalLocation(), tile.getPlane());
			return templateLocation != null && isArenaWallTile(templateLocation.getX(), templateLocation.getY());
		}
		catch (RuntimeException ignored)
		{
			return false;
		}
	}

	private boolean isArenaWallTile(int worldX, int worldY)
	{
		int regionX = worldX - MARKER_REGION_BASE_X;
		int regionY = worldY - MARKER_REGION_BASE_Y;
		if (isInAnyRect(EXCLUDE_RECTS, regionX, regionY))
		{
			return false;
		}

		return OUTER_HIDE_RECT.contains(regionX, regionY) && !INNER_KEEP_RECT.strictlyContains(regionX, regionY);
	}

	private boolean isInAnyRect(Set<TileRectangle> rects, int regionX, int regionY)
	{
		for (TileRectangle rect : rects)
		{
			if (rect.contains(regionX, regionY))
			{
				return true;
			}
		}

		return false;
	}

	private void reloadScene()
	{
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				client.setGameState(GameState.LOADING);
			}
		});
	}

	private void reloadSceneWithCurrentFightState()
	{
		updateConfig();
		clientThread.invoke(() ->
		{
			inPvpArea = isInPvpArea();
			if (shouldRemoveArenaScenery() && client.getGameState() == GameState.LOGGED_IN)
			{
				client.setGameState(GameState.LOADING);
			}
		});
	}

	private void updateConfig()
	{
		removeObstructingScenery = config.removeObstructingPvpArenaScenery();
	}

	private boolean isInPvpArea()
	{
		return AreaDetection.isRawPvpArea(client);
	}

	private boolean shouldRemoveArenaScenery()
	{
		return removeObstructingScenery && AreaDetection.isPvpArenaWorld(client);
	}

	private static final class TileRectangle
	{
		private final int minX;
		private final int minY;
		private final int maxX;
		private final int maxY;

		private TileRectangle(int x1, int y1, int x2, int y2)
		{
			minX = Math.min(x1, x2);
			minY = Math.min(y1, y2);
			maxX = Math.max(x1, x2);
			maxY = Math.max(y1, y2);
		}

		private boolean contains(int x, int y)
		{
			return x >= minX && x <= maxX && y >= minY && y <= maxY;
		}

		private boolean strictlyContains(int x, int y)
		{
			return x > minX && x < maxX && y > minY && y < maxY;
		}
	}
}

package com.wildyqol.updates;

import com.wildyqol.WildyQoLConfig;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;

@Singleton
public class UpdateMessageService
{
	private static final String CONFIG_GROUP = "wildyqol";
	private static final String UPDATE_MESSAGE_150_KEY = "updateMessageShown150";
	private static final String UPDATE_MESSAGE_150 = "<col=00ff00>Wildy QoL 1.5.0:</col><br>"
		+ "Added prayer layout persistence. Your prayer layouts will be remembered and reapplied per character and per LMS / PvP Arena build. (on by default)<br>"
		+ "Updated default warning amounts, clarified plugin settings and messages.";

	private final ConfigManager configManager;
	private final WildyQoLConfig config;
	private final ChatMessageManager chatMessageManager;

	private boolean shouldShowUpdateMessage150;

	@Inject
	private UpdateMessageService(ConfigManager configManager, WildyQoLConfig config, ChatMessageManager chatMessageManager)
	{
		this.configManager = configManager;
		this.config = config;
		this.chatMessageManager = chatMessageManager;
	}

	public void startUp()
	{
		shouldShowUpdateMessage150 = !config.updateMessageShown150();
	}

	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN || !shouldShowUpdateMessage150)
		{
			return;
		}

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(UPDATE_MESSAGE_150)
			.build());
		configManager.setConfiguration(CONFIG_GROUP, UPDATE_MESSAGE_150_KEY, true);
		shouldShowUpdateMessage150 = false;
	}
}

package com.wildyqol.warnings;

import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.function.Predicate;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.util.Text;

@Singleton
public class BankProximityService
{
	private static final int BANK_PROXIMITY_DISTANCE = 10;
	private static final int PVP_RELEVANT_BANK_RADIUS = 20;
	private static final List<WorldPoint> PVP_RELEVANT_BANKS = Arrays.asList(
		new WorldPoint(2443, 3083, 0), // Castle Wars
		new WorldPoint(3164, 3487, 0), // Grand Exchange
		new WorldPoint(3130, 3631, 0), // Ferox Enclave
		new WorldPoint(3094, 3493, 0), // Edgeville
		new WorldPoint(1253, 3741, 0), // Farming Guild
		new WorldPoint(1324, 3824, 0)  // Mount Karuulm
	);

	private final Client client;

	@Inject
	BankProximityService(Client client)
	{
		this.client = client;
	}

	public boolean isBankVisible()
	{
		return isBankVisible(bankLocation -> true);
	}

	public boolean isPvpRelevantBankVisible()
	{
		return isBankVisible(BankProximityService::isPvpRelevantBankLocation);
	}

	private boolean isBankVisible(Predicate<WorldPoint> bankLocationPredicate)
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return false;
		}

		WorldPoint playerLocation = localPlayer.getWorldLocation();
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return false;
		}

		int plane = worldView.getPlane();
		if (hasVisibleBankObject(worldView.getScene(), plane, playerLocation, bankLocationPredicate))
		{
			return true;
		}

		for (NPC npc : client.getNpcs())
		{
			WorldPoint bankLocation = npc.getWorldLocation();
			if (isWithinBankDistance(playerLocation, bankLocation)
				&& bankLocationPredicate.test(bankLocation)
				&& isBankNpc(npc))
			{
				return true;
			}
		}

		return false;
	}

	private boolean hasVisibleBankObject(
		@Nullable Scene scene,
		int plane,
		WorldPoint playerLocation,
		Predicate<WorldPoint> bankLocationPredicate)
	{
		if (scene == null)
		{
			return false;
		}

		Tile[][][] tiles = scene.getTiles();
		if (tiles == null || plane < 0 || plane >= tiles.length || tiles[plane] == null)
		{
			return false;
		}

		for (Tile[] row : tiles[plane])
		{
			if (row == null)
			{
				continue;
			}

			for (Tile tile : row)
			{
				if (isBankTile(tile, playerLocation, bankLocationPredicate))
				{
					return true;
				}
			}
		}

		return false;
	}

	private boolean isBankTile(
		@Nullable Tile tile,
		WorldPoint playerLocation,
		Predicate<WorldPoint> bankLocationPredicate)
	{
		if (tile == null)
		{
			return false;
		}

		if (isBankObjectWithinDistance(tile.getWallObject(), playerLocation, bankLocationPredicate)
			|| isBankObjectWithinDistance(tile.getDecorativeObject(), playerLocation, bankLocationPredicate)
			|| isBankObjectWithinDistance(tile.getGroundObject(), playerLocation, bankLocationPredicate))
		{
			return true;
		}

		GameObject[] gameObjects = tile.getGameObjects();
		if (gameObjects == null)
		{
			return false;
		}

		for (GameObject gameObject : gameObjects)
		{
			if (isBankObjectWithinDistance(gameObject, playerLocation, bankLocationPredicate))
			{
				return true;
			}
		}

		return false;
	}

	private boolean isBankObjectWithinDistance(
		@Nullable TileObject object,
		WorldPoint playerLocation,
		Predicate<WorldPoint> bankLocationPredicate)
	{
		if (object == null)
		{
			return false;
		}

		WorldPoint bankLocation = object.getWorldLocation();
		return isWithinBankDistance(playerLocation, bankLocation)
			&& bankLocationPredicate.test(bankLocation)
			&& isBankObject(object);
	}

	private boolean isBankObject(@Nullable TileObject object)
	{
		if (object == null)
		{
			return false;
		}

		ObjectComposition composition = client.getObjectDefinition(object.getId());
		if (composition == null)
		{
			return false;
		}

		if (composition.getImpostorIds() != null)
		{
			composition = composition.getImpostor();
			if (composition == null)
			{
				return false;
			}
		}

		return hasBankObjectAction(composition);
	}

	private boolean isBankNpc(NPC npc)
	{
		NPCComposition composition = npc.getComposition();
		if (composition == null)
		{
			return false;
		}

		if (composition.getConfigs() != null)
		{
			composition = composition.transform();
			if (composition == null)
			{
				return false;
			}
		}

		return hasBankAction(composition.getActions());
	}

	static boolean isWithinBankDistance(WorldPoint playerLocation, WorldPoint bankLocation)
	{
		return playerLocation.getPlane() == bankLocation.getPlane()
			&& Math.max(
				Math.abs(playerLocation.getX() - bankLocation.getX()),
				Math.abs(playerLocation.getY() - bankLocation.getY())) <= BANK_PROXIMITY_DISTANCE;
	}

	static boolean isPvpRelevantBankLocation(WorldPoint bankLocation)
	{
		for (WorldPoint pvpBank : PVP_RELEVANT_BANKS)
		{
			if (bankLocation.getPlane() == pvpBank.getPlane()
				&& Math.max(
					Math.abs(bankLocation.getX() - pvpBank.getX()),
					Math.abs(bankLocation.getY() - pvpBank.getY())) <= PVP_RELEVANT_BANK_RADIUS)
			{
				return true;
			}
		}

		return false;
	}

	static boolean hasBankAction(@Nullable String[] actions)
	{
		if (actions == null)
		{
			return false;
		}

		for (String action : actions)
		{
			if (action != null && isBankAction(Text.removeTags(action).trim()))
			{
				return true;
			}
		}

		return false;
	}

	static boolean hasBankObjectAction(ObjectComposition composition)
	{
		if (hasBankAction(composition.getActions()))
		{
			return true;
		}

		return isBankObjectName(composition.getName()) && hasUseAction(composition.getActions());
	}

	private static boolean isBankAction(String action)
	{
		return "Bank".equalsIgnoreCase(action);
	}

	private static boolean hasUseAction(@Nullable String[] actions)
	{
		if (actions == null)
		{
			return false;
		}

		for (String action : actions)
		{
			if (action != null && "Use".equalsIgnoreCase(Text.removeTags(action).trim()))
			{
				return true;
			}
		}

		return false;
	}

	private static boolean isBankObjectName(@Nullable String name)
	{
		return name != null && Text.removeTags(name).toLowerCase(Locale.ROOT).contains("bank");
	}
}

package com.wildyqol.warnings;

import com.wildyqol.AreaDetection;
import com.wildyqol.WildyQoLConfig;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

public class ProtectItemInfoBox extends InfoBox
{
	private static final int SPRITE_PRAYER_PROTECT_ITEM = 123;
	private static final int VARBIT_PRAYER_PROTECT_ITEM = 4112;

	private final Client client;
	private final WildyQoLConfig config;

	public ProtectItemInfoBox(WildyQoLConfig config, Client client, Plugin plugin, SpriteManager spriteManager)
	{
		super(null, plugin);
		this.config = config;
		this.client = client;
		spriteManager.getSpriteAsync(SPRITE_PRAYER_PROTECT_ITEM, 0, this);
	}

	@Override
	public String getText()
	{
		return null;
	}

	@Override
	public Color getTextColor()
	{
		return null;
	}

	@Override
	public String getTooltip()
	{
		return "Protect Item is off";
	}

	@Override
	public void setImage(BufferedImage image)
	{
		if (image == null)
		{
			super.setImage(null);
			return;
		}

		BufferedImage combined = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = combined.createGraphics();
		g.drawImage(image, 0, 0, null);

		// Draw red cross in bottom right
		g.setColor(Color.RED);
		int w = combined.getWidth();
		int h = combined.getHeight();

		// Thick red cross
		// \
		g.drawLine(w - 10, h - 10, w - 2, h - 2);
		g.drawLine(w - 10, h - 9, w - 3, h - 2); // thickness

		// /
		g.drawLine(w - 10, h - 2, w - 2, h - 10);
		g.drawLine(w - 9, h - 2, w - 2, h - 9); // thickness

		g.dispose();
		super.setImage(combined);
	}

	@Override
	public boolean render()
	{
		if (!config.protectItemInfoBox() || !shouldNotifyProtectItem())
		{
			return false;
		}

		return super.render();
	}

	private boolean shouldNotifyProtectItem()
	{
		if (!PvpArea.isPvpArea(client))
		{
			return false;
		}

		if (AreaDetection.isDeadmanWorld(client)
			|| AreaDetection.isActiveLmsGame(client)
			|| AreaDetection.isPvpArenaMatch(client))
		{
			return false;
		}

		// Check if Protect Item is active
		boolean protectItemActive = client.getVarbitValue(VARBIT_PRAYER_PROTECT_ITEM) == 1;

		return !protectItemActive;
	}
}

