package com.wildyqol.warnings;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

@Singleton
public class WarningOverlay extends OverlayPanel
{
	private static final int WARNING_PANEL_WIDTH = 175;
	private static final Color CRITICAL_WARNING_COLOR = Color.RED;
	private static final Color CAUTION_WARNING_COLOR = Color.ORANGE;

	private final WarningServiceManager warningServiceManager;

	@Inject
	WarningOverlay(WarningServiceManager warningServiceManager)
	{
		this.warningServiceManager = warningServiceManager;
		setPosition(OverlayPosition.TOP_LEFT);
		setPreferredSize(new Dimension(WARNING_PANEL_WIDTH, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		setPreferredSize(new Dimension(WARNING_PANEL_WIDTH, 0));

		List<WarningLine> warnings = orderWarnings(warningServiceManager.getOverlayWarnings());
		if (warnings.isEmpty())
		{
			return null;
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left(warnings.size() == 1 ? "PvP setup warning" : "PvP setup warnings")
			.leftColor(Color.WHITE)
			.build());

		for (WarningLine warning : warnings)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("- " + warning.getText())
				.leftColor(colorForWarning(warning.getSeverity()))
				.build());
		}
		return super.render(graphics);
	}

	static List<WarningLine> orderWarnings(List<WarningLine> warnings)
	{
		List<WarningLine> orderedWarnings = new ArrayList<>(warnings);
		orderedWarnings.sort((left, right) -> Integer.compare(
			severityRank(left.getSeverity()),
			severityRank(right.getSeverity())));
		return orderedWarnings;
	}

	static Color colorForWarning(WarningSeverity severity)
	{
		return severity == WarningSeverity.CAUTION ? CAUTION_WARNING_COLOR : CRITICAL_WARNING_COLOR;
	}

	private static int severityRank(WarningSeverity severity)
	{
		return severity == WarningSeverity.CAUTION ? 1 : 0;
	}
}

package com.wildyqol.warnings;

import com.wildyqol.WildyQoLConfig.WarningDisplayMode;
import java.util.Collections;
import java.util.List;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GraphicChanged;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;

public abstract class WarningService<T>
{
	private final Client client;
	private final ClientThread clientThread;
	private final WarningEligibilityService warningEligibilityService;
	private final Function<T, String> textProvider;
	private final Function<T, WarningSeverity> severityProvider;
	private final WarningVisibility<T> visibility;

	private List<T> visibleWarnings = Collections.emptyList();

	protected WarningService(
		Client client,
		ClientThread clientThread,
		WarningEligibilityService warningEligibilityService,
		Function<T, String> textProvider,
		Function<T, WarningSeverity> severityProvider)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.warningEligibilityService = warningEligibilityService;
		this.textProvider = textProvider;
		this.severityProvider = severityProvider;
		this.visibility = new WarningVisibility<>(textProvider);
	}

	public void startUp()
	{
		refreshOnClientThread();
	}

	public void shutDown()
	{
		visibleWarnings = Collections.emptyList();
		visibility.reset();
	}

	public void onItemContainerChanged(ItemContainerChanged event)
	{
	}

	public void onVarbitChanged(VarbitChanged event)
	{
	}

	public void onGameTick(GameTick event)
	{
		update(true);
	}

	public void onChatMessage(ChatMessage event)
	{
	}

	public void onMenuOptionClicked(MenuOptionClicked event)
	{
	}

	public void onGraphicChanged(GraphicChanged event)
	{
	}

	public void onHitsplatApplied(HitsplatApplied event)
	{
	}

	public List<WarningLine> getOverlayWarnings()
	{
		if (!isEnabled() || visibleWarnings.isEmpty())
		{
			return Collections.emptyList();
		}

		return visibleWarnings.stream()
			.map(warning -> new WarningLine(severityProvider.apply(warning), textProvider.apply(warning)))
			.collect(Collectors.toList());
	}

	public void refresh()
	{
		update(false);
	}

	public void refreshOnClientThread()
	{
		clientThread.invokeLater(this::refresh);
	}

	protected abstract boolean isEnabled();

	protected abstract List<T> evaluateAll();

	private void update(boolean gameTick)
	{
		boolean enabled = isEnabled();
		if (!enabled || client.getGameState() != GameState.LOGGED_IN)
		{
			visibleWarnings = visibility.update(
				Collections.emptyList(),
				enabled,
				WarningDisplayMode.ALWAYS,
				false,
				false,
				gameTick);
			return;
		}

		WarningEligibility eligibility = warningEligibilityService.getEligibility();
		if (!eligibility.isEquipmentWarningsVisible())
		{
			visibleWarnings = visibility.update(
				Collections.emptyList(),
				enabled,
				WarningDisplayMode.ALWAYS,
				false,
				false,
				gameTick);
			return;
		}

		List<T> warnings = enabled ? evaluateAll() : Collections.emptyList();
		if (warnings.isEmpty())
		{
			visibleWarnings = visibility.update(warnings, enabled, WarningDisplayMode.ALWAYS, false, false, gameTick);
			return;
		}

		visibleWarnings = visibility.update(
			warnings,
			enabled,
			eligibility.getWarningDisplayMode(),
			eligibility.isInPvp(),
			eligibility.isEligibleOutsidePvp(),
			gameTick);
	}
}

package com.wildyqol.warnings;

import com.google.common.collect.ImmutableList;
import com.wildyqol.warnings.ammo.RangedAmmoWarningService;
import com.wildyqol.warnings.charges.ItemChargeWarningService;
import com.wildyqol.warnings.magic.MagicSpellbookWarningService;
import com.wildyqol.warnings.teleport.TeleportOutWarningService;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GraphicChanged;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetLoaded;

@Singleton
public class WarningServiceManager
{
	private final WarningEligibilityService warningEligibilityService;
	private final ItemChargeWarningService itemChargeWarningService;
	private final List<WarningService<?>> services;

	@Inject
	WarningServiceManager(
		WarningEligibilityService warningEligibilityService,
		RangedAmmoWarningService rangedAmmoWarningService,
		ItemChargeWarningService itemChargeWarningService,
		MagicSpellbookWarningService magicSpellbookWarningService,
		TeleportOutWarningService teleportOutWarningService)
	{
		this.warningEligibilityService = warningEligibilityService;
		this.itemChargeWarningService = itemChargeWarningService;
		services = ImmutableList.of(
			rangedAmmoWarningService,
			itemChargeWarningService,
			magicSpellbookWarningService,
			teleportOutWarningService);
	}

	public void startUp()
	{
		warningEligibilityService.reset();
		services.forEach(WarningService::startUp);
	}

	public void shutDown()
	{
		warningEligibilityService.reset();
		services.forEach(WarningService::shutDown);
	}

	public void onItemContainerChanged(ItemContainerChanged event)
	{
		services.forEach(service -> service.onItemContainerChanged(event));
	}

	public void onVarbitChanged(VarbitChanged event)
	{
		services.forEach(service -> service.onVarbitChanged(event));
	}

	public void onGameTick(GameTick event)
	{
		warningEligibilityService.onGameTick(event);
		services.forEach(service -> service.onGameTick(event));
	}

	public void onChatMessage(ChatMessage event)
	{
		services.forEach(service -> service.onChatMessage(event));
		if (warningEligibilityService.onChatMessage(event))
		{
			services.forEach(WarningService::refreshOnClientThread);
		}
	}

	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		services.forEach(service -> service.onMenuOptionClicked(event));
	}

	public void onGraphicChanged(GraphicChanged event)
	{
		services.forEach(service -> service.onGraphicChanged(event));
	}

	public void onHitsplatApplied(HitsplatApplied event)
	{
		services.forEach(service -> service.onHitsplatApplied(event));
	}

	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (warningEligibilityService.onWidgetLoaded(event))
		{
			services.forEach(WarningService::refreshOnClientThread);
		}
	}

	public void refreshOnClientThread()
	{
		services.forEach(WarningService::refreshOnClientThread);
	}

	public void onRuneScapeProfileChanged()
	{
		itemChargeWarningService.onRuneScapeProfileChanged();
	}

	public List<WarningLine> getOverlayWarnings()
	{
		List<WarningLine> warnings = new ArrayList<>();
		for (WarningService<?> service : services)
		{
			for (WarningLine warning : service.getOverlayWarnings())
			{
				boolean alreadyIncluded = warnings.stream()
					.anyMatch(included -> included.getText().equals(warning.getText()));
				if (!alreadyIncluded)
				{
					warnings.add(warning);
				}
			}
		}
		return warnings;
	}
}

package com.wildyqol.warnings;

public enum WarningSeverity
{
	CRITICAL,
	CAUTION
}

package com.wildyqol.warnings;

import com.google.common.collect.ImmutableList;
import com.wildyqol.WildyQoLConfig.WarningDisplayMode;
import java.util.List;
import java.util.Optional;
import java.util.function.Function;
import javax.annotation.Nullable;

public class WarningVisibility<T>
{
	public static final int PVP_GRACE_TICKS = 15;

	private final Function<T, String> textProvider;

	@Nullable
	private String pvpGraceWarningText;
	private int pvpGraceTicksRemaining;

	public WarningVisibility(Function<T, String> textProvider)
	{
		this.textProvider = textProvider;
	}

	public List<T> update(
		List<T> warnings,
		boolean enabled,
		WarningDisplayMode warningDisplayMode,
		boolean inPvp,
		boolean eligibleOutsidePvp,
		boolean gameTick)
	{
		if (!enabled || warnings.isEmpty())
		{
			reset();
			return ImmutableList.of();
		}

		if (warningDisplayMode == WarningDisplayMode.ALWAYS)
		{
			reset();
			return warnings;
		}

		if (warningDisplayMode == WarningDisplayMode.PVP_AREA)
		{
			reset();
			return inPvp ? warnings : ImmutableList.of();
		}

		if (inPvp && gameTick && pvpGraceTicksRemaining > 0)
		{
			pvpGraceTicksRemaining--;
		}

		if (!inPvp)
		{
			if (!eligibleOutsidePvp)
			{
				reset();
				return ImmutableList.of();
			}

			pvpGraceWarningText = getWarningKey(warnings);
			pvpGraceTicksRemaining = PVP_GRACE_TICKS;
			return warnings;
		}

		String warningKey = getWarningKey(warnings);
		if (pvpGraceTicksRemaining <= 0 || !warningKey.equals(pvpGraceWarningText))
		{
			return ImmutableList.of();
		}

		return warnings;
	}

	public Optional<T> update(
		Optional<T> warning,
		boolean enabled,
		WarningDisplayMode warningDisplayMode,
		boolean inPvp,
		boolean eligibleOutsidePvp,
		boolean gameTick)
	{
		List<T> warnings = warning
			.map(ImmutableList::of)
			.orElseGet(ImmutableList::of);
		List<T> visibleWarnings = update(warnings, enabled, warningDisplayMode, inPvp, eligibleOutsidePvp, gameTick);
		return visibleWarnings.isEmpty() ? Optional.empty() : Optional.of(visibleWarnings.get(0));
	}

	public void reset()
	{
		pvpGraceWarningText = null;
		pvpGraceTicksRemaining = 0;
	}

	private String getWarningKey(List<T> warnings)
	{
		StringBuilder key = new StringBuilder();
		for (T warning : warnings)
		{
			if (key.length() > 0)
			{
				key.append('\n');
			}
			key.append(textProvider.apply(warning));
		}
		return key.toString();
	}
}

package com.wildyqol.warnings.ammo;

public interface AmmoThresholds
{
	int atlatlDarts();

	int bolts();

	int javelins();

	int arrows();
}

package com.wildyqol.warnings.ammo;

import com.google.common.collect.ImmutableMap;
import com.google.common.collect.ImmutableList;
import com.google.common.collect.ImmutableSet;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import net.runelite.api.ItemID;
import net.runelite.client.game.ItemVariationMapping;

public class RangedAmmoEvaluator
{
	private static final Map<Integer, String> AMMO_NAMES = buildAmmoNames();

	public Optional<RangedAmmoWarning> evaluate(RangedAmmoState state, AmmoThresholds thresholds)
	{
		List<RangedAmmoWarning> warnings = evaluateAll(state, thresholds);
		return warnings.isEmpty() ? Optional.empty() : Optional.of(warnings.get(0));
	}

	public List<RangedAmmoWarning> evaluateAll(RangedAmmoState state, AmmoThresholds thresholds)
	{
		return evaluateAll(state, thresholds, true);
	}

	public List<RangedAmmoWarning> evaluateAll(
		RangedAmmoState state,
		AmmoThresholds thresholds,
		boolean warnSuboptimalAmmo)
	{
		Set<RangedAmmoRequirement> requirements = state.getRequirements();
		if (requirements.isEmpty())
		{
			return ImmutableList.of();
		}

		List<RangedAmmoWarning> warnings = new ArrayList<>();
		warnings.addAll(evaluateAmmo(requirements, state.getAmmoCounts(), thresholds));
		if (warnSuboptimalAmmo)
		{
			warnings.addAll(evaluateSuboptimalAmmo(requirements, state.getAmmoCounts()));
		}
		warnings.sort((left, right) ->
		{
			int priority = left.getPriority().compareTo(right.getPriority());
			return priority != 0 ? priority : left.getText().compareTo(right.getText());
		});
		return ImmutableList.copyOf(warnings);
	}

	private List<RangedAmmoWarning> evaluateSuboptimalAmmo(
		Set<RangedAmmoRequirement> requirements,
		Map<Integer, Integer> ammoCounts)
	{
		List<RangedAmmoWarning> warnings = new ArrayList<>();
		for (RangedAmmoRequirement requirement : requirements)
		{
			int compatibleCount = countAmmo(requirement.getAcceptedAmmoIds(), ammoCounts);
			int optimalCount = countOptimalAmmo(requirement, ammoCounts);
			if (compatibleCount > 0 && optimalCount == 0)
			{
				String ammoText = findSuboptimalAmmoText(requirement, ammoCounts)
					.map(ammoName -> "Suboptimal ammo: " + ammoName)
					.orElse("Suboptimal ammo");
				warnings.add(new RangedAmmoWarning(
					RangedAmmoWarning.WarningPriority.SUBOPTIMAL,
					ammoText));
			}
		}
		return ImmutableList.copyOf(warnings);
	}

	private Optional<String> findSuboptimalAmmoText(
		RangedAmmoRequirement requirement,
		Map<Integer, Integer> ammoCounts)
	{
		String bestAmmoText = null;
		int bestQuantity = 0;
		for (Map.Entry<Integer, Integer> ammoCount : ammoCounts.entrySet())
		{
			int quantity = ammoCount.getValue();
			int ammoId = ammoCount.getKey();
			int mappedAmmoId = ItemVariationMapping.map(ammoId);
			if (quantity <= 0
				|| !requirement.getAcceptedAmmoIds().contains(mappedAmmoId)
				|| isOptimalAmmo(requirement, ammoId))
			{
				continue;
			}

			String ammoText = AMMO_NAMES.get(mappedAmmoId);
			if (ammoText == null)
			{
				continue;
			}

			if (quantity > bestQuantity
				|| quantity == bestQuantity && (bestAmmoText == null || ammoText.compareTo(bestAmmoText) < 0))
			{
				bestAmmoText = ammoText;
				bestQuantity = quantity;
			}
		}
		return Optional.ofNullable(bestAmmoText);
	}

	private List<RangedAmmoWarning> evaluateAmmo(
		Set<RangedAmmoRequirement> requirements,
		Map<Integer, Integer> ammoCounts,
		AmmoThresholds thresholds)
	{
		if (requirements.isEmpty())
		{
			return ImmutableList.of();
		}

		List<RangedAmmoWarning> warnings = new ArrayList<>();
		for (RangedAmmoRequirement requirement : requirements)
		{
			int compatibleCount = countCompatibleAmmo(requirement, ammoCounts);
			if (compatibleCount == 0)
			{
				boolean wrongAmmo = requirements.size() == 1 && !ammoCounts.isEmpty();
				String missingText = hasMultipleRequirementsForAmmoFamily(requirement, requirements)
					? requirement.getSpecificText()
					: requirement.getAmmoFamilyText();
				String text = wrongAmmo
					? "Wrong " + requirement.getWrongText()
					: "No " + missingText;
				warnings.add(new RangedAmmoWarning(
					wrongAmmo ? RangedAmmoWarning.WarningPriority.WRONG : RangedAmmoWarning.WarningPriority.MISSING,
					text));
			}
		}

		for (RangedAmmoRequirement requirement : requirements)
		{
			int threshold = requirement.getThreshold(thresholds);
			if (threshold <= 0)
			{
				continue;
			}

			int compatibleCount = countCompatibleAmmo(requirement, ammoCounts);
			if (compatibleCount > 0 && compatibleCount < threshold)
			{
				String lowText = hasMultipleRequirementsForAmmoFamily(requirement, requirements)
					? requirement.getSpecificText()
					: requirement.getAmmoFamilyText();
				warnings.add(new RangedAmmoWarning(
					RangedAmmoWarning.WarningPriority.LOW,
					"Low " + lowText + ": " + compatibleCount + "/" + threshold));
			}
		}

		return ImmutableList.copyOf(warnings);
	}

	private boolean hasMultipleRequirementsForAmmoFamily(
		RangedAmmoRequirement requirement,
		Set<RangedAmmoRequirement> requirements)
	{
		int matchingRequirements = 0;
		for (RangedAmmoRequirement other : requirements)
		{
			if (other.getAmmoFamilyText().equals(requirement.getAmmoFamilyText()) && ++matchingRequirements > 1)
			{
				return true;
			}
		}
		return false;
	}

	private int countCompatibleAmmo(RangedAmmoRequirement requirement, Map<Integer, Integer> ammoCounts)
	{
		return countAmmo(requirement.getAcceptedAmmoIds(), ammoCounts);
	}

	private int countAmmo(Set<Integer> ammoIds, Map<Integer, Integer> ammoCounts)
	{
		int count = 0;
		for (Map.Entry<Integer, Integer> ammoCount : ammoCounts.entrySet())
		{
			if (ammoIds.contains(ItemVariationMapping.map(ammoCount.getKey())))
			{
				count += ammoCount.getValue();
			}
		}
		return count;
	}

	private int countOptimalAmmo(RangedAmmoRequirement requirement, Map<Integer, Integer> ammoCounts)
	{
		int count = 0;
		for (Map.Entry<Integer, Integer> ammoCount : ammoCounts.entrySet())
		{
			if (isOptimalAmmo(requirement, ammoCount.getKey()))
			{
				count += ammoCount.getValue();
			}
		}
		return count;
	}

	private boolean isOptimalAmmo(RangedAmmoRequirement requirement, int itemId)
	{
		return requirement.getExactOptimalAmmoIds().contains(itemId)
			|| requirement.getOptimalAmmoIds().contains(ItemVariationMapping.map(itemId));
	}

	public static RangedAmmoState state(
		Set<RangedAmmoRequirement> requirements,
		Map<Integer, Integer> ammoCounts)
	{
		EnumMap<RangedAmmoRequirement, RangedAmmoRequirement> orderedRequirements = new EnumMap<>(RangedAmmoRequirement.class);
		for (RangedAmmoRequirement requirement : requirements)
		{
			orderedRequirements.put(requirement, requirement);
		}

		Map<Integer, Integer> rawAmmoCounts = new HashMap<>();
		ammoCounts.forEach((itemId, quantity) ->
		{
			if (quantity > 0)
			{
				rawAmmoCounts.merge(itemId, quantity, Integer::sum);
			}
		});

		return new RangedAmmoState(
			ImmutableSet.copyOf(orderedRequirements.keySet()),
			ImmutableMap.copyOf(rawAmmoCounts));
	}

