	{
		switch (this)
		{
			case ATLATL_DARTS:
				return "atlatl ammo";
			case RUNE_BOLTS:
			case DRAGON_BOLTS:
				return "crossbow ammo";
			case ANTLER_BOLTS:
				return "antler crossbow ammo";
			case DRAGON_JAVELINS:
				return "ballista ammo";
			case DRAGON_ARROWS:
				return "bow ammo";
			default:
				throw new IllegalStateException("Unsupported ammo requirement: " + this);
		}
	}

	int getThreshold(AmmoThresholds thresholds)
	{
		return threshold.applyAsInt(thresholds);
	}

	Set<Integer> getAcceptedAmmoIds()
	{
		return acceptedAmmoIds;
	}

	Set<Integer> getOptimalAmmoIds()
	{
		return optimalAmmoIds;
	}

