		SharedStateStore sharedStateStore = sharedStateStore(temporaryFolder.newFolder().toPath());
		PrayerLayoutStore store = new PrayerLayoutStore(new Gson(), sharedStateStore);
		PrayerLayoutContext account = PrayerLayoutContext.account("profile-a", "Player");
		PrayerLayoutContext pure = PrayerLayoutContext.minigame(PrayerLayoutBuild.PURE);
		PrayerLayoutSnapshot accountLayout = snapshot("prayer_order_book_0", "1,2,3");
		PrayerLayoutSnapshot pureLayout = snapshot("prayer_hidden_book_0_2", "true");

		store.save(account, accountLayout);
		store.save(pure, pureLayout);
		store.flush();

		assertEquals(accountLayout, store.load(account));
		assertEquals(pureLayout, store.load(pure));
		assertEquals(
			new Gson().toJson(accountLayout),
			sharedStateStore.readCharacter("profile-a").get("prayer.layout"));
		assertEquals(
			new Gson().toJson(pureLayout),
			sharedStateStore.readShared().get("prayer.prayerLayoutPure"));
	}

	private PrayerLayoutSnapshot snapshot(String key, String value)
	{
		return new PrayerLayoutSnapshot(Collections.singletonMap(key, value));
	}

	private SharedStateStore sharedStateStore(Path directory) throws Exception
	{
		Constructor<SharedStateStore> constructor = SharedStateStore.class.getDeclaredConstructor(
			Gson.class,
			Path.class,
			Executor.class);
		constructor.setAccessible(true);
		return constructor.newInstance(new Gson(), directory, (Executor) Runnable::run);
	}
}

package com.wildyqol.pvparena;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.wildyqol.WildyQoLConfig;
import com.wildyqol.WildyQoLConfig.PvpArenaSpellbookWarningMode;
import org.junit.Test;

public class PvpArenaSpellbookWarningEvaluatorTest
{
	private static final int BUILD_MAIN = 0;
	private static final int BUILD_ZERK = 1;
	private static final int BUILD_PURE = 2;
	private static final int OWN_ANCIENT = 0;
	private static final int OWN_STANDARD = 1;
	private static final int OWN_LUNAR = 2;
	private static final int OPPONENT_STANDARD = 0;
	private static final int OPPONENT_ANCIENT = 1;
	private static final int OPPONENT_LUNAR = 2;

	private final PvpArenaSpellbookWarningEvaluator evaluator = new PvpArenaSpellbookWarningEvaluator();

	@Test
	public void configDefaultsToAncient()
	{
		WildyQoLConfig config = new WildyQoLConfig()
		{
		};

		assertTrue(config.pvpArenaSpellbookWarningMode() == PvpArenaSpellbookWarningMode.ANCIENT);
	}

	@Test
	public void ancientModeAcceptsBothAncient()
	{
		PvpArenaSpellbookWarning warning = evaluate(
			PvpArenaSpellbookWarningMode.ANCIENT,
			BUILD_MAIN,
			OWN_ANCIENT,
			OWN_STANDARD,
			OWN_LUNAR,
			OPPONENT_ANCIENT);

		assertFalse(warning.hasWarning());
	}

	@Test
	public void ancientModeFlagsOwnAndOpponentIndependently()
	{
		PvpArenaSpellbookWarning warning = evaluate(
			PvpArenaSpellbookWarningMode.ANCIENT,
			BUILD_ZERK,
			OWN_ANCIENT,
			OWN_STANDARD,
			OWN_LUNAR,
			OPPONENT_STANDARD);

		assertTrue(warning.hasWarning());
		assertTrue(warning.isOwnSpellbookOffending());
		assertTrue(warning.isOpponentSpellbookOffending());
	}

	@Test
	public void fixedModesUseSelectedTargetSpellbook()
	{
		assertFalse(evaluate(PvpArenaSpellbookWarningMode.STANDARD, BUILD_MAIN, OWN_STANDARD, OWN_ANCIENT, OWN_LUNAR, OPPONENT_STANDARD).hasWarning());
		assertFalse(evaluate(PvpArenaSpellbookWarningMode.LUNAR, BUILD_PURE, OWN_STANDARD, OWN_ANCIENT, OWN_LUNAR, OPPONENT_LUNAR).hasWarning());
		assertTrue(evaluate(PvpArenaSpellbookWarningMode.STANDARD, BUILD_MAIN, OWN_ANCIENT, OWN_ANCIENT, OWN_LUNAR, OPPONENT_STANDARD).isOwnSpellbookOffending());
		assertTrue(evaluate(PvpArenaSpellbookWarningMode.LUNAR, BUILD_PURE, OWN_STANDARD, OWN_ANCIENT, OWN_LUNAR, OPPONENT_STANDARD).isOpponentSpellbookOffending());
	}

	@Test
	public void playersMatchModeWarnsWhenActiveOwnKitDiffersFromOpponent()
	{
		PvpArenaSpellbookWarning matching = evaluate(
			PvpArenaSpellbookWarningMode.PLAYERS_MATCH,
			BUILD_MAIN,
			OWN_ANCIENT,
			OWN_STANDARD,
			OWN_LUNAR,
			OPPONENT_ANCIENT);
		PvpArenaSpellbookWarning mismatching = evaluate(
			PvpArenaSpellbookWarningMode.PLAYERS_MATCH,
			BUILD_MAIN,
			OWN_ANCIENT,
			OWN_STANDARD,
			OWN_LUNAR,
			OPPONENT_STANDARD);

		assertFalse(matching.hasWarning());
		assertTrue(mismatching.isOwnSpellbookOffending());
		assertTrue(mismatching.isOpponentSpellbookOffending());
	}

	@Test
	public void neverModeDoesNotWarn()
	{
		PvpArenaSpellbookWarning warning = evaluate(
			PvpArenaSpellbookWarningMode.NEVER,
			BUILD_MAIN,
			OWN_STANDARD,
			OWN_STANDARD,
			OWN_LUNAR,
			OPPONENT_STANDARD);

		assertFalse(warning.hasWarning());
	}

	@Test
	public void activeBuildSelectsCorrectOwnSpellbook()
	{
		PvpArenaSpellbookWarning mainWarning = evaluate(
			PvpArenaSpellbookWarningMode.ANCIENT,
			BUILD_MAIN,
			OWN_STANDARD,
			OWN_ANCIENT,
			OWN_ANCIENT,
			OPPONENT_ANCIENT);
		PvpArenaSpellbookWarning zerkWarning = evaluate(
			PvpArenaSpellbookWarningMode.ANCIENT,
			BUILD_ZERK,
			OWN_ANCIENT,
			OWN_STANDARD,
			OWN_ANCIENT,
			OPPONENT_ANCIENT);
		PvpArenaSpellbookWarning pureWarning = evaluate(
			PvpArenaSpellbookWarningMode.ANCIENT,
			BUILD_PURE,
			OWN_ANCIENT,
			OWN_ANCIENT,
			OWN_STANDARD,
			OPPONENT_ANCIENT);

		assertTrue(mainWarning.isOwnSpellbookOffending());
		assertTrue(zerkWarning.isOwnSpellbookOffending());
		assertTrue(pureWarning.isOwnSpellbookOffending());
	}

	@Test
	public void unknownValuesDoNotWarn()
	{
		assertFalse(evaluate(PvpArenaSpellbookWarningMode.ANCIENT, 99, OWN_STANDARD, OWN_STANDARD, OWN_STANDARD, OPPONENT_STANDARD).hasWarning());
		assertFalse(evaluate(PvpArenaSpellbookWarningMode.ANCIENT, BUILD_MAIN, 99, OWN_STANDARD, OWN_STANDARD, OPPONENT_STANDARD).hasWarning());
		assertFalse(evaluate(PvpArenaSpellbookWarningMode.ANCIENT, BUILD_MAIN, OWN_STANDARD, OWN_STANDARD, OWN_STANDARD, 99).hasWarning());
	}

	private PvpArenaSpellbookWarning evaluate(
		PvpArenaSpellbookWarningMode mode,
		int activeBuild,
		int mainSpellbook,
		int zerkSpellbook,
		int pureSpellbook,
		int opponentSpellbook)
	{
		return evaluator.evaluate(
			mode,
			activeBuild,
			mainSpellbook,
			zerkSpellbook,
			pureSpellbook,
			opponentSpellbook);
	}
}

package com.wildyqol.scenery;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.wildyqol.WildyQoLConfig;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.EnumSet;
import java.util.concurrent.atomic.AtomicBoolean;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WorldType;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import org.junit.Test;

public class EmirsArenaSceneryServiceTest
{
	@Test
	public void pvpVarbitChangeDoesNotReloadSceneOutsidePvpArenaWorld() throws Exception
	{
		AtomicBoolean sceneReloaded = new AtomicBoolean(false);
		EmirsArenaSceneryService service = service(EnumSet.noneOf(WorldType.class), true, sceneReloaded);

		service.onVarbitChanged(varbitChanged(VarbitID.PVP_AREA_CLIENT, 1));

		assertFalse(sceneReloaded.get());
	}

	@Test
	public void pvpVarbitChangeReloadsSceneInPvpArenaWorld() throws Exception
	{
		AtomicBoolean sceneReloaded = new AtomicBoolean(false);
		EmirsArenaSceneryService service = service(EnumSet.of(WorldType.PVP_ARENA), true, sceneReloaded);

		service.onVarbitChanged(varbitChanged(VarbitID.PVP_AREA_CLIENT, 1));

		assertTrue(sceneReloaded.get());
	}

	private static EmirsArenaSceneryService service(
		EnumSet<WorldType> worldTypes,
		boolean rawPvpArea,
		AtomicBoolean sceneReloaded) throws Exception
	{
		EmirsArenaSceneryService service = new EmirsArenaSceneryService();
		setField(service, "client", client(worldTypes, rawPvpArea, sceneReloaded));
		setField(service, "clientThread", new ImmediateClientThread());
		setField(service, "config", config(true));
		setField(service, "removeObstructingScenery", true);
		setField(service, "inPvpArea", false);
		return service;
	}

	private static Client client(
		EnumSet<WorldType> worldTypes,
		boolean rawPvpArea,
		AtomicBoolean sceneReloaded)
	{
		return (Client) Proxy.newProxyInstance(
			Client.class.getClassLoader(),
			new Class<?>[] {Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getWorldType":
						return worldTypes;
					case "getVarbitValue":
						int varbitId = (int) args[0];
						return varbitId == VarbitID.INSIDE_WILDERNESS || varbitId == VarbitID.PVP_AREA_CLIENT
							? rawPvpArea ? 1 : 0
							: 0;
					case "getGameState":
						return GameState.LOGGED_IN;
					case "setGameState":
						sceneReloaded.set(args[0] == GameState.LOADING);
						return null;
					case "toString":
						return "client";
					default:
						return defaultValue(method.getReturnType());
				}
			});
	}

	private static WildyQoLConfig config(boolean removeObstructingScenery)
	{
		return (WildyQoLConfig) Proxy.newProxyInstance(
			WildyQoLConfig.class.getClassLoader(),
			new Class<?>[] {WildyQoLConfig.class},
			(proxy, method, args) ->
			{
				if ("removeObstructingPvpArenaScenery".equals(method.getName()))
				{
					return removeObstructingScenery;
				}

				if ("toString".equals(method.getName()))
				{
					return "config";
				}

				Object defaultValue = method.getDefaultValue();
				return defaultValue != null ? defaultValue : defaultValue(method.getReturnType());
			});
	}

	private static VarbitChanged varbitChanged(int varbitId, int value)
	{
		VarbitChanged event = new VarbitChanged();
		event.setVarbitId(varbitId);
		event.setValue(value);
		return event;
	}

	private static void setField(Object target, String name, Object value) throws Exception
	{
		Field field = target.getClass().getDeclaredField(name);
		field.setAccessible(true);
		field.set(target, value);
	}

	private static Object defaultValue(Class<?> type)
	{
		if (!type.isPrimitive())
		{
			return null;
		}

		if (type == boolean.class)
		{
			return false;
		}

		if (type == void.class)
		{
			return null;
		}

		return 0;
	}

	private static class ImmediateClientThread extends ClientThread
	{
		@Override
		public void invoke(Runnable r)
		{
			r.run();
		}
	}
}

package com.wildyqol.warnings;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.lang.reflect.Proxy;
import net.runelite.api.ObjectComposition;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class BankProximityServiceTest
{
	@Test
	public void bankActionCounts()
	{
		assertTrue(BankProximityService.hasBankAction(new String[] {"Talk-to", "Bank"}));
		assertTrue(BankProximityService.hasBankAction(new String[] {"<col=ffff00>Bank</col>"}));
		assertTrue(BankProximityService.hasBankObjectAction(
			objectComposition("Bank chest", new String[] {"<col=ffff00>Use</col>"})));
	}

	@Test
	public void nonBankActionsDoNotCount()
	{
		assertFalse(BankProximityService.hasBankAction(new String[] {"Deposit", "Collect"}));
		assertFalse(BankProximityService.hasBankAction(new String[] {"Use"}));
		assertFalse(BankProximityService.hasBankObjectAction(objectComposition("Chest", new String[] {"Use"})));
		assertFalse(BankProximityService.hasBankAction(new String[] {null, "Banker"}));
		assertFalse(BankProximityService.hasBankAction(null));
	}

	@Test
	public void bankDistanceIsTenTilesOnSamePlane()
	{
		WorldPoint playerLocation = new WorldPoint(3200, 3200, 0);

		assertTrue(BankProximityService.isWithinBankDistance(playerLocation, new WorldPoint(3210, 3200, 0)));
		assertTrue(BankProximityService.isWithinBankDistance(playerLocation, new WorldPoint(3210, 3210, 0)));
		assertFalse(BankProximityService.isWithinBankDistance(playerLocation, new WorldPoint(3211, 3200, 0)));
		assertFalse(BankProximityService.isWithinBankDistance(playerLocation, new WorldPoint(3210, 3200, 1)));
	}

	@Test
	public void pvpRelevantBanksUseTwentyTileRadius()
	{
		assertTrue(BankProximityService.isPvpRelevantBankLocation(new WorldPoint(2443, 3083, 0)));
		assertTrue(BankProximityService.isPvpRelevantBankLocation(new WorldPoint(2463, 3103, 0)));
		assertTrue(BankProximityService.isPvpRelevantBankLocation(new WorldPoint(3164, 3487, 0)));
		assertTrue(BankProximityService.isPvpRelevantBankLocation(new WorldPoint(3130, 3631, 0)));
		assertTrue(BankProximityService.isPvpRelevantBankLocation(new WorldPoint(3094, 3493, 0)));
		assertTrue(BankProximityService.isPvpRelevantBankLocation(new WorldPoint(1253, 3741, 0)));
		assertTrue(BankProximityService.isPvpRelevantBankLocation(new WorldPoint(1324, 3824, 0)));

		assertFalse(BankProximityService.isPvpRelevantBankLocation(new WorldPoint(2464, 3103, 0)));
		assertFalse(BankProximityService.isPvpRelevantBankLocation(new WorldPoint(2443, 3083, 1)));
	}

	private ObjectComposition objectComposition(String name, String[] actions)
	{
		return (ObjectComposition) Proxy.newProxyInstance(
			ObjectComposition.class.getClassLoader(),
			new Class<?>[] {ObjectComposition.class},
			(proxy, method, args) ->
			{
				if ("getName".equals(method.getName()))
				{
					return name;
				}

				if ("getActions".equals(method.getName()))
				{
					return actions;
				}

				if (method.getReturnType().equals(int.class))
				{
					return 0;
				}

				return null;
			});
	}
}

