		AccountType accountType,
		EnumSet<WorldType> worldTypes,
		int skullIcon,
		boolean inPvp,
		boolean activeLmsGame)
	{
		return client(accountType, worldTypes, skullIcon, new AtomicBoolean(inPvp), activeLmsGame);
	}

	private static Client client(
		AccountType accountType,
		EnumSet<WorldType> worldTypes,
		int skullIcon,
		AtomicBoolean inPvp)
	{
		return client(accountType, worldTypes, skullIcon, inPvp, false);
	}

	private static Client client(
		AccountType accountType,
		EnumSet<WorldType> worldTypes,
		int skullIcon,
		AtomicBoolean inPvp,
		boolean activeLmsGame)
	{
		return (Client) Proxy.newProxyInstance(
			Client.class.getClassLoader(),
			new Class<?>[] {Client.class},
			(proxy, method, args) ->
			{
				if ("getWorldType".equals(method.getName()))
				{
					return worldTypes;
				}

				if ("getVarbitValue".equals(method.getName()))
				{
					int varbitId = (int) args[0];
					if (varbitId == VarbitID.BR_INGAME)
					{
						return activeLmsGame ? 1 : 0;
					}

					if (varbitId == VarbitID.INSIDE_WILDERNESS || varbitId == VarbitID.PVP_AREA_CLIENT)
					{
						return inPvp.get() ? 1 : 0;
					}

					return 0;
				}

				if ("getLocalPlayer".equals(method.getName()))
				{
					return player(skullIcon);
				}

				if ("getAccountType".equals(method.getName()))
				{
					return accountType;
				}

				if ("toString".equals(method.getName()))
				{
					return "clientOutsidePvp";
				}

				return null;
			});
	}

	private static Player player(int skullIcon)
	{
		return (Player) Proxy.newProxyInstance(
			Player.class.getClassLoader(),
			new Class<?>[] {Player.class},
			(proxy, method, args) ->
			{
				if ("getSkullIcon".equals(method.getName()))
				{
					return skullIcon;
				}

				if ("toString".equals(method.getName()))
				{
					return "player";
				}

				return null;
			});
	}

	private static BankProximityService bankProximityService(boolean bankVisible, boolean pvpRelevantBankVisible)
	{
		return new BankProximityService(null)
		{
			@Override
			public boolean isBankVisible()
			{
				return bankVisible;
			}

			@Override
			public boolean isPvpRelevantBankVisible()
			{
				return pvpRelevantBankVisible;
			}
		};
	}
}

package com.wildyqol.warnings;

import static org.junit.Assert.assertEquals;

import java.awt.Color;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class WarningOverlayTest
{
	@Test
	public void cautionSeverityUsesCautionColor()
	{
		assertEquals(Color.ORANGE, WarningOverlay.colorForWarning(WarningSeverity.CAUTION));
	}

	@Test
	public void criticalSeverityUsesCriticalColor()
	{
		assertEquals(Color.RED, WarningOverlay.colorForWarning(WarningSeverity.CRITICAL));
	}

	@Test
	public void ordersCriticalWarningsBeforeCautionWarnings()
	{
		WarningLine lowCharges = new WarningLine(WarningSeverity.CAUTION, "Low tome of fire charges: 200/500");
		WarningLine missingTeleBlock = new WarningLine(WarningSeverity.CRITICAL, "No Tele Block casts");
		WarningLine suboptimalAmmo = new WarningLine(WarningSeverity.CAUTION, "Suboptimal ammo: Ruby dragon bolts");
		WarningLine missingTeleport = new WarningLine(WarningSeverity.CRITICAL, "No teleport out");

		List<WarningLine> warnings = WarningOverlay.orderWarnings(Arrays.asList(
			lowCharges,
			missingTeleBlock,
			suboptimalAmmo,
			missingTeleport));

		assertEquals(Arrays.asList(
			missingTeleBlock,
			missingTeleport,
			lowCharges,
			suboptimalAmmo), warnings);
	}
}

