		assertTrue(evaluate(0, ItemID.SKILLS_NECKLACE1).isEmpty());
		assertTrue(evaluate(0, ItemID.SLAYER_RING_1).isEmpty());
		assertTrue(evaluate(0, ItemID.SLAYER_RING_ETERNAL).isEmpty());
